(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-chunked-prefill-decode"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-1\">一 · 事故现场：一条长 prompt 如何让整批 decode 停摆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-2\">二 · 它到底解决什么：把两种瓶颈叠进同一轮迭代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-3\">三 · 适用边界的正面：什么样的负载配方才吃得到收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-4\">四 · 适用边界的反面：它明确不解决的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-5\">五 · 代价的分解：抖动、开销与饥饿三条线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-6\">六 · 工程判断：先确认病因，再决定是否上这套机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-7\">七 · 长预填独占SM引发的decode停摆：事故形态与算法边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-8\">八 · 调度器入口：两条队列与一次token预算切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-9\">九 · 拼批与地址装配：分页 KV 块与中间状态的落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-10\">十 · 统一 kernel 模板：因果掩码与单 token 查询的同构化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-11\">十一 · chunk 完成判定与队列回流：入队、转段与饥饿抑制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-12\">十二 · 迭代级代价核算：气泡消除的账与新增的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-13\">十三 · 预算方程与饥饿边界：chunk 配额的分配逻辑与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-14\">十四 · 边界条件：预算挤占、块粒度与调度器自身成为瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-15\">十五 · 迭代时间下界的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-16\">十六 · token 预算约束与配额的动态分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-17\">十七 · 统一 kernel 模板下的掩码与查询形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-18\">十八 · 中间状态保存与 chunk 重入队的代价模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-19\">十九 · 稳定性技巧与失败模式的判别信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-20\">二十 · 与相邻算法的公式级差别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-21\">二十一 · 背驮调度的失效边界：预算挤占、块粒度与饥饿回路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-22\">二十二 · 请求形态：混合长度样本池是唯一能吃到红利的负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-23\">二十三 · 长度分布：chunk 尺寸必须与 prompt 长度分位数对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-24\">二十四 · 并发与批大小：按 token 预算计批，而非按请求数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-25\">二十五 · SLO 配方：TTFT 与 TPOT 必须同时进入调度决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-26\">二十六 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-27\">二十七 · 配方核对清单与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-28\">二十八 · 负载配方与失效边界：什么时候该背驮，什么时候不该</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-29\">二十九 · 硬件档位：先定 SM 预算，再定卡数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-30\">三十 · 并行拓扑：同池内的 TP/EP 与副本切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-31\">三十一 · 量化方案：精度档位与 chunk 中间状态的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-32\">三十二 · KV 策略：分页块、中间状态与驱逐顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-33\">三十三 · 调度参数：token 预算、chunk 配额与 SLO 反馈环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-34\">三十四 · 可复现配置的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-35\">三十五 · 迭代时间的双瓶颈分解与利用率上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-36\">三十六 · 显存：中间状态保存与分页块的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-37\">三十七 · 带宽：decode 的命脉被 chunk 的读写挤兑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-38\">三十八 · 通信：张量并行下 chunk 的集合通信放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-39\">三十九 · 功耗与尾延迟：SLO 约束下的真实上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-40\">四十 · 规模上去以后哪里先崩：一条判定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-41\">四十一 · 规模上去以后，先崩的是 token 预算而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-42\">四十二 · 单批 token 预算封顶：规模上去先崩在调度器与 TPOT 抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-43\">四十三 · 精度漂移：chunk 边界上的数值不连续</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-44\">四十四 · OOM：中间状态与分页 KV 的叠加峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-45\">四十五 · 批抖动：TPOT 在 prefill 高峰的锯齿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-46\">四十六 · 路由不均与长 prompt 饥饿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-47\">四十七 · 尾延迟尖刺的定位与回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-48\">四十八 · 当互补失效：五类故障的判据、观测点与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-49\">四十九 · 对照轴：资源互补、池边界与显存粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-50\">五十 · 决策表：五族算法的适用条件与代价位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-51\">五十一 · 判定式：什么时候背驮会输给邻居</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-52\">五十二 · 叠加与互斥：与正交算法的组合次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-53\">五十三 · 规模上限与选型收口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-decode-sec-54\">五十四 · 同族算法怎么选：分块背驮的边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:517px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 516.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器维护decode运行队列与prefill等待队列，按token预算而…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每轮从等待队列取一个chunk（如512 token）与全部decode序…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">attention对chunk用因果掩码、对decode用单token查询…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">chunk完成后若prompt未耗尽则重新入队，已耗尽则转入decode队列</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按decode序列的SLO与chunk进度动态调整每轮chunk toke…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-chunked-prefill-decode-sec-1\">一 · 事故现场：一条长 prompt 如何让整批 decode 停摆</h3>\n<p>某 RL rollout 服务在混合长度样本池上跑得好好的，直到样本池里混进一批超长 prompt。现象不是“慢一点”，而是断崖：短 rollout 的 p99 尾延迟从稳态水平突然拉长数倍，GPU 利用率与 token 吞吐同时掉下去——注意，这两者同向下降是判断病因的关键指纹。若只是算力不够，利用率会顶满而吞吐受限；若只是显存不够，会出现抢占与重算。两者一起掉，说明 SM 在“忙等”与“空转”之间来回切换，中间夹着气泡。</p>\n<p>病因在调度粒度。传统连续批处理按请求数组批：一个长 prompt 的 prefill 是一段计算密集的长任务，一旦进入批次就独占 SM 直到整段 prompt 算完。在这段时间里，所有已经在跑的 decode 序列无法获得新的迭代步——它们的单 token 前向被推迟，TPOT 被拉长；而 decode 阶段本该吃满的显存带宽此时闲置。等 prefill 结束，decode 批次才恢复，但队列里已经积压了新的短请求，尾延迟被二次放大。用迭代时间的粗粒度模型看：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>当 $s_{\\text{chunk}}$ 等于整段长 prompt 时，第一项远大于第二项，$\\text{util}$ 的分子里只有计算时间被有效利用，带宽时间被浪费；反过来在纯 decode 迭代里，第一项接近零而第二项主导，算力又被浪费。两种迭代各自只用一个瓶颈资源，交替出现就形成了利用率的结构性缺口。这就是“气泡”的定量含义：不是某一刻的偶发空闲，而是迭代级资源互补关系的缺失。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-2\">二 · 它到底解决什么：把两种瓶颈叠进同一轮迭代</h3>\n<p>分块预填背驮解码（chunked prefill piggybacking decode）的靶心只有一个：让 prefill 的计算密集段与 decode 的带宽密集段在同一批次内共存，用 decode 的带宽空闲填补 prefill 的计算占用，用 prefill 的算力占用填补 decode 的算力空闲。它不解决显存分配粒度问题——那是分页 KV 批量 Rollout 的职责；它也不把两个阶段拆到不同 GPU 池——那是预填解码分离 Rollout 的职责。本算法坚持同池部署，靠时间维度上的拼批而非空间维度上的拆池来消除气泡。</p>\n<p>机制按数据流顺序展开：调度器维护两个队列，decode 运行队列与 prefill 等待队列，批的计量单位是 token 预算而非请求个数。每轮从等待队列取一个固定大小的 chunk（如 512 token），与全部在跑 decode 序列拼成一个 batch。attention 对 chunk 用因果掩码、对 decode 用单 token 查询，两者走同一 kernel 模板，避免为两种形态各写一套 kernel 带来的启动开销与模板分裂。chunk 算完后，若 prompt 未耗尽则重新入队等待下一轮，若已耗尽则该序列转入 decode 队列开始自回归。</p>\n<p>核心调度约束是一行预算等式：</p>\n<div class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</div>\n<p>其中 $B_{\\text{decode}}$ 是在跑 decode 序列的 token 配额，$B_{\\text{chunk}}$ 是本轮从等待队列取的 prefill 块大小。二者按 SLO 动态分配：decode 的 TPOT 约束紧时压低 $B_{\\text{chunk}}$，长 prompt 的 TTFT 约束紧时抬高 $B_{\\text{chunk}}$。这条等式是本算法全部稳定性技巧的落点——它用 token 预算把两类负载的资源占用隔离开，防止长 prompt 把短请求饿死。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-3\">三 · 适用边界的正面：什么样的负载配方才吃得到收益</h3>\n<p>收益成立的前提是“混合”。请求形态必须是长短混合样本池：池子里既有几百 token 的短 rollout，也有数千 token 的长 prompt，且两者共享同一批 GPU。此时每一轮迭代天然具备互补条件——decode 序列提供稳定的带宽需求，chunk 提供稳定的算力需求，$\\max$ 的两项被拉平，$\\text{util}$ 上升。若样本池长度高度同质，要么全是长 prompt（每轮都在做 prefill，decode 队列空，拼批无从谈起），要么全是短请求（chunk 太小，拼批的调度开销盖过收益），本算法退化为普通连续批处理。</p>\n<p>第二个前提是同池部署。拆池方案把 prefill 与 decode 放到不同 GPU 池，用跨池 KV 传输换隔离性，代价是传输带宽与池间负载不均；本算法不拆池，收益来自“不搬运”的零拷贝拼批，代价是 decode 序列必须容忍 TPOT 抖动。因此它适合对 TPOT 有弹性、对尾延迟敏感的在线 rollout，而不适合 TPOT 硬约束极紧的交互式场景——后者应走分离式预填解码。</p>\n<p>第三个前提是 SLO 同时约束两端：decode 的 TPOT 与长 prompt 的 TTFT 都要有明确上限，且 chunk 进度被纳入调度决策以抑制长 prompt 饥饿。缺少进度反馈时，调度器会持续偏袒 decode（因为 decode 的 TPOT 违约更直观），长 prompt 反复入队却拿不到配额，TTFT 无界增长。这是本算法最隐蔽的失败模式，也是“按 token 预算而非请求数组批”这一设计必须配进度信号的原因。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-4\">四 · 适用边界的反面：它明确不解决的问题</h3>\n<p>第一，它不解决显存碎片与 KV 分配粒度。chunk 之间的中间状态需要保存，KV 沿用分页块管理，但分页本身不是本算法的内容；显存利用率的上限由分页策略决定，拼批只提升时间维度的利用率。第二，它不解决跨节点通信与并行策略——单节点多卡张量并行是它的典型部署形态，通信开销由 NVLink 与集合通信库承担，本算法不改变通信拓扑。第三，它不解决量化精度问题：量化档位在部署配方中未给出，NVFP4/FP8 的数值稳定性是独立条目的话题，拼批既不改善也不恶化数值行为，但 chunk 切分会让中间状态的保存与恢复多一层精度路径，需要与量化策略对齐。</p>\n<p>第四，也是最容易被误用的边界：它不适用于 chunk 极小化的场景。chunk 切分引入额外 kernel 启动与中间状态保存，chunk 过小时调度开销占比上升，调度器本身成为瓶颈——此时拼批带来的利用率收益被启动开销吃掉，甚至净负。规模上限受单批 token 预算与 kernel 启动开销共同约束：预算越大，单轮拼批越饱满，但单轮迭代时间越长，TPOT 抖动幅度越大；预算越小，抖动越小，但调度频率上升。这个权衡没有普适最优点，只能按 SLO 与硬件启动开销标定。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-5\">五 · 代价的分解：抖动、开销与饥饿三条线</h3>\n<p>第一条代价线是 decode 的 TPOT 抖动。decode 序列被 chunk 挤占 token 预算，在 prefill 高峰时段 TPOT 超出稳态值。抖动幅度与 $B_{\\text{chunk}}/B_{\\text{iter}}$ 正相关：chunk 占比越高，单轮迭代里 decode 能推进的 token 越少，TPOT 越长。工程判断是给 TPOT 设一个抖动上限，把 $B_{\\text{chunk}}$ 的动态调整约束在该上限内，而不是让调度器自由追求利用率最大化。</p>\n<p>第二条代价线是调度开销。chunk 切分意味着每轮多一次 kernel 启动、多一次中间状态写回与读取；chunk 越小，这些固定开销在迭代时间中的占比越高。定性地说，当 chunk 小到与单次 kernel 启动开销同量级时，拼批的收益被开销抵消。512 token 这一档位是给定事实中的锚点，它对应的判断是：chunk 大小应显著大于启动开销折算出的等效 token 数，否则应放弃切分、退回整段 prefill。</p>\n<p>第三条代价线是长 prompt 饥饿。长 prompt 反复入队但 chunk 配额被 decode 挤占，TTFT 无界增长。抑制手段是把 chunk 进度纳入每轮配额决策：进度落后于 TTFT 约束的 prompt 获得配额优先级，进度充裕的让位给 decode。这条线与第一条线直接冲突——两者争夺同一个 $B_{\\text{chunk}}$，调度器的本质工作就是在 TPOT 抖动上限与 TTFT 上限之间做带约束的分配。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-6\">六 · 工程判断：先确认病因，再决定是否上这套机制</h3>\n<p>上线前的第一步不是调 chunk 大小，而是确认病因确实是迭代级气泡。判据是三条同向指标：GPU 利用率下降、token 吞吐下降、短 rollout 的 p99 尾延迟上升，且三者同时出现于长 prompt 进入样本池之后。若利用率顶满而吞吐不动，病因在算力或通信；若出现显存抢占与重算，病因在 KV 分配，应转分页 KV 批量 Rollout；若 TPOT 硬约束被突破且不可放宽，病因在阶段耦合，应转预填解码分离 Rollout。只有确认是“两种瓶颈交替、互补缺失”的气泡，本算法才是对的工具。</p>\n<p>确认之后，标定顺序是：先按硬件 kernel 启动开销定 chunk 下限，再按 TPOT 抖动上限定 $B_{\\text{chunk}}/B_{\\text{iter}}$ 的上限，最后按 TTFT 约束定 chunk 进度的优先级曲线。三步都落在同一条预算等式上，任何一步越界都会把收益转成代价。这套机制的工程价值不在于“更快”，而在于把一条不可控的长任务拆成可调度的固定块，让调度器第一次拥有在 prefill 与 decode 之间分配资源的显式旋钮——旋钮的代价是抖动与开销，收益是尾延迟与利用率，取舍必须由 SLO 而非默认参数决定。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-7\">七 · 长预填独占SM引发的decode停摆：事故形态与算法边界</h3>\n<p>一次典型的线上事故形态是这样：RL rollout 的样本池里混着极长 prompt（数千到上万 token）与大量短请求。调度器按请求数组批处理，某个长 prompt 的 prefill 被整块提交，计算密集的注意力与前馈在数百毫秒内独占全部 SM；与此同时，已经进入 decode 阶段的序列因拿不到 SM 而整批停摆。表现为 GPU 利用率曲线出现周期性凹陷、token 吞吐同步下滑、短 rollout 的 p99 尾延迟被长 prompt 拉长。这不是显存不足，也不是带宽打满，而是计算资源被单一长任务垄断造成的调度气泡——分页 KV 批量 Rollout 解决的是显存分配粒度，预填解码分离 Rollout 把两阶段拆到不同 GPU 池，两者都不处理“同池内长任务阻塞短任务”的问题，这正是本算法要填的洞。</p>\n<p>把长 prefill 切成固定 token 块（如 512 token），与在跑 decode 序列拼成同一批次，本质是把两个瓶颈互补的阶段叠在一个迭代里。迭代时间由计算侧与带宽侧的较大者决定：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>chunk 提供计算占用，decode 提供显存带宽占用，二者在同一 kernel 模板内并行（chunk 走因果掩码、decode 走单 token 查询），util 因此被抬高。但这条公式同时暴露了边界：当 chunk 的计算时间显著超过 decode 的带宽时间，迭代就被计算侧钉住，decode 的 TPOT 随 chunk 大小线性恶化；反之 chunk 太小则计算侧填不满，带宽侧反而成为唯一瓶颈，互补失效。</p>\n<p>调度约束是每轮 token 预算的硬切分：</p>\n<div class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</div>\n<p>二者按 SLO 动态分配，chunk 进度用于抑制长 prompt 饥饿。失效条件有三类。其一，chunk 过小：切分引入额外 kernel 启动与中间状态保存，调度开销占比上升，调度器本身成为瓶颈，规模上限受单批 token 预算与 kernel 启动开销约束。其二，decode 序列被 chunk 挤占 token 预算：prefill 高峰时段 TPOT 抖动超出 SLO，对延迟敏感的在线服务不可接受。其三，长 prompt 反复入队但 chunk 配额持续被 decode 挤占，出现长 prompt 饥饿，TTFT 反而恶化。因此它适合混合长度样本池、prefill 与 decode 同池部署、SLO 同时约束 TPOT 与 TTFT 的场景；不适合 decode 占绝对多数、TPOT 极紧的纯在线推理，也不适合单条 prompt 长到 chunk 队列永远排不上的极端分布——那种情形应交给分离式预填/解码，用独立 GPU 池隔离计算密集阶段。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>后果</th><th>工程判断</th></tr></thead><tbody><tr><td>chunk 过小</td><td>kernel 启动与状态保存开销占比升</td><td>设 chunk 下限，监控调度开销占比</td></tr><tr><td>decode 预算被挤</td><td>TPOT 抖动超 SLO</td><td>按 TPOT 反推 B_decode 下限</td></tr><tr><td>chunk 配额长期不足</td><td>长 prompt 饥饿，TTFT 恶化</td><td>按 chunk 进度设最低配额</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-decode-sec-8\">八 · 调度器入口：两条队列与一次token预算切分</h3>\n<p>背驮解码的每一次迭代都从调度器的一次“取件”开始。调度器手里握着两条队列：decode 运行队列装着已经进入自回归阶段、每轮只吐一个 token 的序列；prefill 等待队列装着尚未完成首段计算的请求，按到达顺序或 SLO 紧迫度排序。关键动作不是按请求数凑批，而是先算出一个迭代级 token 预算 <span class=\"formula-inline\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span>，再把这个预算切成两半：<span class=\"formula-inline\">$$B_{\\text{decode}}$$</span> 留给在跑 decode 序列的 token 配额，<span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 留给从等待队列头部取出的一块 prefill。</p>\n<p>这一步的输入是两条队列的当前长度、每条 decode 序列的 TPOT 余量、以及等待队列头部请求的已推进 chunk 进度；输出是一个混合 batch 的成员清单与各自分到的 token 数。代价落在调度器自身：切分要在微秒级完成，因为它处在每轮迭代的关键路径上。若 <span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 被压到很小（例如远低于 512 token 的锚点），调度决策频率上升，调度器 CPU 侧开销开始与 GPU kernel 启动开销叠加，成为吞吐的隐性上限——这正是失败模式里“chunk 过小导致调度开销占比上升”的第一现场。</p>\n<p>具体例子：一个长短混合样本池里，等待队列头部是一条 8K token 的长 prompt，decode 队列里有 30 条已生成若干 token 的短序列。调度器不会等长 prompt 整体算完，而是先给它切出 512 token 的 chunk，把剩余预算按各 decode 序列的 SLO 紧迫度分配下去，拼成一个 batch 送进模型。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-9\">九 · 拼批与地址装配：分页 KV 块与中间状态的落位</h3>\n<p>成员清单确定后，下一步是把这些逻辑序列装配成 GPU 能直接寻址的物理布局。decode 序列各自持有一串已分配的分页 KV 块，本轮只需为每条序列追加一个 token 的 KV 槽位；prefill chunk 则需要为这 512 个 token 新分配 KV 块，并在块表里登记。装配的产物是一张 batch 级的块表与位置索引，attention kernel 靠它把逻辑位置映射到物理块。</p>\n<p>这一步的代价是显存侧的：chunk 的 KV 写入量与 chunk token 数成正比，而 decode 序列每轮只写一个 token 的 KV，二者在同一轮里争抢 HBM 写带宽。分页块管理保证了分配粒度不因 chunk 而变粗，但也意味着块表条目随 batch 规模增长，装配阶段要遍历的元数据量上升。更隐蔽的代价是 prefill 中间状态：chunk 之间需要保存已算部分的注意力上下文，若 chunk 被切得很碎，这份中间状态的保存与恢复次数随之增加。</p>\n<p>公式层面，本轮迭代时间由两条路径的较大者决定：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>它说明拼批的目标是让计算密集的 prefill 项与带宽密集的 decode 项在时间上尽量重叠，util 越接近 1，说明两条路径被填得越满。工程判断是：<span class=\"formula-inline\">$$s_{\\text{chunk}}$$</span> 取 512 这类固定值时，prefill 项与 decode 项的量级要大致可比，否则 max 会退化为单边瓶颈，背驮失去意义。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-10\">十 · 统一 kernel 模板：因果掩码与单 token 查询的同构化</h3>\n<p>拼好的 batch 进入 attention 计算时，走的是一套统一 kernel 模板，而不是为 prefill 和 decode 各写一条路径。对 chunk 内的 token，查询向量按因果掩码只 attend 到自身及之前的 chunk 内位置，加上此前已完成的 KV；对 decode 序列，查询是单 token，attend 到全部历史 KV。两者在模板里共享同一套块级加载、softmax 归一与输出写回逻辑，差异只体现在掩码与查询长度参数上。</p>\n<p>同构化的收益是 kernel 启动次数被压到每轮一次（或每层一次），避免了 prefill kernel 与 decode kernel 交替启动带来的空档；代价是模板必须同时容纳两种查询形态，寄存器与共享内存的占用按较长的那条路径配置，decode 序列在这一轮里被迫按 chunk 的规格走，单 token 查询的轻量优势被部分抵消。这就是 decode TPOT 在 prefill 高峰时段抖动的 kernel 层根源：decode 序列的 token 预算被 chunk 挤占，且它要与 chunk 共享同一模板的资源规格。</p>\n<p>具体例子：30 条 decode 序列的单 token 查询与一条 512 token 的 chunk 在同一模板里展开，chunk 的因果掩码把 512×512 的块内注意力限制在下三角，decode 的 30 个查询各自对全长 KV 做点积。若这一轮 <span class=\"formula-inline\">$$B_{\\text{decode}}$$</span> 被压得过低，decode 序列的查询数减少，模板的并行度下降，单轮 TPOT 上升。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-11\">十一 · chunk 完成判定与队列回流：入队、转段与饥饿抑制</h3>\n<p>一轮计算结束后，调度器要对 chunk 做完成判定：若该 prompt 的 token 尚未耗尽，chunk 重新回到 prefill 等待队列，带着更新后的进度；若已耗尽，请求转入 decode 运行队列，开始自回归。这个判定看似简单，却是饥饿问题的发生点——长 prompt 反复入队，但每轮分到的 <span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 被 decode 序列的 SLO 挤占，进度推进极慢，形成长 prompt 饥饿。</p>\n<p>抑制手段是按 decode 序列 SLO 与 chunk 进度动态调整每轮 chunk token 配额：当某条长 prompt 的已推进比例落后于其 TTFT 约束所要求的时间线时，调度器在下一轮把 <span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 上调，压缩 <span class=\"formula-inline\">$$B_{\\text{decode}}$$</span>。这一步的输入是各请求的 SLO 余量与 chunk 进度，输出是下一轮的预算切分；代价直接体现在 decode 侧：被压缩的 decode 配额转化为 TPOT 抖动，若抖动超出 SLO，调度器又要把配额还回去，形成来回拉扯。</p>\n<p>具体例子：一条 8K token 的长 prompt 按 512 token 切块需 16 轮才能完成 prefill。若每轮都被 decode 挤到只给 128 token，则需 64 轮，其 TTFT 被拉长数倍；调度器检测到进度落后后上调配额，代价是同期 30 条短序列的 TPOT 出现一个尖峰。这就是“尾延迟下降”与“TPOT 抖动”在同一机制里的两面。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-12\">十二 · 迭代级代价核算：气泡消除的账与新增的账</h3>\n<p>把上述步骤串起来看，背驮解码消除的是 prefill 独占 SM 造成的气泡：原本长 prompt 的 prefill 会让 decode 批次整段停摆，GPU 利用率与 token 吞吐同时下跌；现在 prefill 的计算占用被 decode 的带宽空闲填补，迭代级利用率提升。这笔账的收益在混合长度样本池里最明显，短 rollout 不再被长 prompt 阻塞，p99 尾延迟下降。</p>\n<p>但新增的账要逐项记：chunk 切分引入额外 kernel 启动与中间状态保存，chunk 越小，这部分开销占比越高；decode 序列被 chunk 挤占 token 预算，TPOT 在 prefill 高峰抖动；调度器处在每轮关键路径上，切分与回流判定的 CPU 开销随迭代频率上升。规模上限因此受三重约束：单批 token 预算、kernel 启动开销、调度器吞吐。工程判断是，chunk 取 512 token 这类固定值时，要把每轮迭代的 prefill 项与 decode 项控制在可比量级，并让调度器的切分逻辑足够轻，否则背驮带来的 util 增益会被调度开销吃掉。</p>\n<p>与相邻算法的分工在此清晰：分页 KV 批量 Rollout 解决的是显存分配粒度，预填解码分离 Rollout 把两阶段拆到不同 GPU 池，而本算法坚持同池、同批次内互补计算与带宽瓶颈，不拆池——代价是 TPOT 抖动与调度开销必须自己消化，收益是不必承担跨池传输与池间负载不均。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-13\">十三 · 预算方程与饥饿边界：chunk 配额的分配逻辑与失效面</h3>\n<p>把机制落到调度器内部，真正决定成败的不是“切块”这个动作，而是每轮迭代里 <span class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span> 这条预算约束怎么解。$B_{\\text{decode}}$ 不是常数：它等于当前 decode 运行队列中所有活跃序列的 token 配额之和，随到达率与序列长度实时变化；$B_{\\text{chunk}}$ 则是从 prefill 等待队列头部取出的块大小（典型值 512 token）。调度器每轮先锁定 decode 侧的最小配额（由 TPOT 的 SLO 反推：TPOT 上限除以单 token 迭代时间下界，得到每轮至少要推进的 decode token 数），剩余预算才给 chunk。这意味着 chunk 的实际大小是一个被挤压后的余量，而不是固定 512——当 decode 队列膨胀时，$B_{\\text{chunk}}$ 会被压到远小于 512，甚至归零，此时长 prompt 只能继续排队。饥饿就发生在这个余量长期为零的区间：长 prompt 反复入队、反复拿不到配额，TTFT 无界增长，而调度器自身因为每轮都要重算配额并做队列重排，反而成为 CPU 侧瓶颈。</p>\n<p>从单轮迭代的代价看，两个阶段共享同一个 kernel 模板，但资源画像完全不同。prefill chunk 是计算密集的：其耗时近似 <span class=\"formula\">$$\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}}$$</span>，随 chunk 线性增长，且因果掩码使 chunk 内部 token 之间产生 $O(s_{\\text{chunk}}^2)$ 的注意力交互；decode 侧则是带宽密集的：<span class=\"formula\">$$\\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}$$</span>，每步只推进一个 token，却要把整份 KV cache 从 HBM 读一遍。两者拼批后，迭代时间由较慢的一侧决定，利用率 <span class=\"formula\">$$\\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</span> 才有机会接近 1——这正是“背驮”的收益来源：prefill 的算力占用填补了 decode 留下的带宽空闲，反之亦然。但代价是 chunk 切分带来的额外 kernel 启动与中间状态保存：每个 chunk 结束时，该 prompt 已算出的 KV 必须落回分页块管理，下一轮再从等待队列取出时重新装载注意力状态。chunk 越小，这部分固定开销在迭代时间中的占比越高，当 $s_{\\text{chunk}}$ 降到数十 token 量级，启动开销会吞掉互补收益，调度器从“填气泡”变成“造气泡”。</p>\n<p>失效条件可以按三条边界来判。第一条是 TPOT 抖动边界：decode 序列被 chunk 挤占 token 预算时，其单步推进被拉长，prefill 高峰时段 TPOT 出现周期性尖峰，若尖峰超出 SLO 上限，说明 $B_{\\text{decode}}$ 的最小配额设得过低，需要把 decode 配额从“余量分配”改为“硬保留”。第二条是 chunk 过小边界：当 $B_{\\text{chunk}}$ 长期低于某个阈值（由 kernel 启动开销与单 chunk 计算量之比决定），调度开销占比上升，此时应改为让长 prompt 独占若干轮完整迭代，而不是继续细切。第三条是饥饿边界：长 prompt 的 chunk 进度必须作为调度器的显式状态参与配额竞争，例如按已推进 token 数给予优先级加权，否则纯 FIFO 加余量分配会让长 prompt 在 decode 队列饱和时永久排队。三条边界共同给出规模上限：单批 token 预算受 KV 分页块容量与 kernel 启动开销约束，超出后互补效应消失。一个具体例子：混合样本池中同时存在 4K token 的长 rollout prompt 与数十 token 的短请求，短请求持续到达使 decode 队列维持在高位，若调度器只按余量给 chunk，长 prompt 的 TTFT 会被拉到与短请求吞吐同量级的退化区间；把 chunk 配额改为按进度加权并保留 decode 硬配额后，长 prompt 以每轮固定块推进，短请求 TPOT 稳定在 SLO 内，代价是长 prompt 的完成时间被拉长但可预测——这正是该方案在 RL rollout 场景下的工程取舍：用可预测的 TTFT 换稳定的 TPOT。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-14\">十四 · 边界条件：预算挤占、块粒度与调度器自身成为瓶颈</h3>\n<p>这套机制的健康运行依赖一个隐含前提：每轮迭代中，prefill 的计算占用与 decode 的带宽占用能在时间上真正重叠。一旦这个前提被打破，互补就退化为挤占。核心约束是每轮 token 预算 <span class=\"formula-inline\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span>，其中 <span class=\"formula-inline\">$$B_{\\text{decode}}$$</span> 是在跑 decode 序列的配额，<span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 是从等待队列取的 prefill 块大小。当 decode 队列本身很长、SLO 对 TPOT 的要求收紧时，调度器必须把 <span class=\"formula-inline\">$$B_{\\text{decode}}$$</span> 抬高，<span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 相应压缩，长 prompt 每轮只能推进很小的块，反复入队却推进缓慢——这就是长 prompt 饥饿。反过来，若为了压 TTFT 而放大 chunk，decode 序列的 token 预算被挤占，TPOT 在 prefill 高峰时段出现抖动并可能越出 SLO。判断失效的第一个信号不是平均吞吐，而是 decode TPOT 的 p99 与长 prompt 的 TTFT 是否同时逼近各自上限。</p>\n<p>第二个边界是块粒度。chunk 切分本身要付两笔固定成本：每块的 kernel 启动开销，以及块间必须保存的 prefill 中间状态（注意力已算部分的 KV、未耗尽的 prompt 位置信息）。块越小，这两笔成本在每轮迭代中的占比越高，调度器每轮要做的队列操作与配额决策次数也越多，最终瓶颈从 SM 转移到 CPU 侧调度。以 512 token 为块时，一个数千 token 的长 prompt 需要若干轮才能耗尽，每轮都触发一次拼接、一次 kernel 模板调用、一次状态落盘；若把块降到很小，迭代次数成倍上升，启动开销与状态保存的绝对量虽未变，但相对每轮有效计算的比例急剧恶化。规模上限因此由单批 token 预算与 kernel 启动开销共同封顶，而不是由 GPU 算力封顶。</p>\n<p>第三个边界是同池部署假设。该方案不拆池，prefill 与 decode 共享同一组 SM 与同一份 KV 分页块空间，因此它无法像预填解码分离那样把两阶段放到不同 GPU 池上各自按最优形态配置。当样本池长度分布极端偏斜——极少数超长 prompt 与大量极短 rollout 混跑——单批 token 预算会被超长 prompt 的 chunk 持续占用一部分，短请求的尾延迟改善有限。此时更合适的做法是转向分离式预填/解码，把长 prompt 的确定性计算负载隔离出去；而分页 KV 批量 Rollout 解决的是显存分配粒度问题，与本方案不在同一层面，二者可叠加但不可互相替代。工程判断的落点是：先测 decode TPOT 的抖动幅度与 chunk 相关的调度开销占比，若前者越界则调低 <span class=\"formula-inline\">$$B_{\\text{chunk}}$$</span> 上限，若后者越界则调高块大小并接受 TTFT 变长，二者不可同时满足时即应放弃同池方案。</p>\n<h3 id=\"alg-chunked-prefill-decode-sec-15\">十五 · 迭代时间下界的逐项拆解</h3>\n<p>核心公式把一轮迭代的耗时压成两个下界中的较大者：<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right)$$</div>这里 <em>C</em><sub>pre</sub> 是每 token 的 prefill 计算代价（以 FLOP 计，随模型宽度、层数、序列位置线性或二次增长），<em>s</em><sub>chunk</sub> 是本轮取出的 chunk token 数，FLOPS 是这批 SM 在目标精度下可持续的算力；<em>C</em><sub>dec</sub> 是每 decode token 需要搬运的权重与 KV 字节数，<em>s</em><sub>dec</sub> 是本轮参与解码的序列数，BW 是 HBM 有效带宽。两项分别代表计算受限与带宽受限的路径，取 max 意味着二者中较慢的那条决定节拍——这正是背驮的立足点：prefill 项吃算力，decode 项吃带宽，两条路径在同一 SM 上争用的是不同资源，因此并行不会简单相加。</p>\n<p>推导的关键一步在于把“串行两段”改写为“并行两段”。若不做背驮，一轮内先跑 prefill 再跑 decode，耗时是两项之和；背驮后二者共享同一 kernel 启动窗口，耗时退化为两项的 max。收益的解析表达即 <em>T</em><sub>serial</sub> − <em>T</em><sub>iter</sub> = min(两项)，但只有当两项量级接近时才真正兑现——若 <em>s</em><sub>chunk</sub> 过大，prefill 项远超 decode 项，decode 序列被拖到 prefill 的节拍上，TPOT 抖动；若 <em>s</em><sub>chunk</sub> 过小，decode 项主导，chunk 的推进速度被 decode 的带宽节拍锁死，长 prompt 的 TTFT 反而拉长。调度器的任务就是让两项在每一轮都尽量贴近。</p>\n<p>利用率项 <div class=\"formula\">$$\\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>是诊断工具而非优化目标。<em>T</em><sub>compute</sub> 与 <em>T</em><sub>mem</sub> 分别是本轮实际花在计算与访存上的时间，二者之和若接近 <em>T</em><sub>iter</sub>，说明两条路径被填满；若明显小于，说明 SM 在等调度、等 kernel 启动或等中间状态读写。工程上应把 util 按轮采样，与 chunk 大小做二维对照：util 随 <em>s</em><sub>chunk</sub> 上升而上升，到某一拐点后因 prefill 项压过 decode 项而 plateaus，该拐点即当前负载下的最优 chunk 配额。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-16\">十六 · token 预算约束与配额的动态分配</h3>\n<p>每轮预算写成 <div class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</div>其中 <em>B</em><sub>decode</sub> 是在跑 decode 序列的 token 配额，<em>B</em><sub>chunk</sub> 是从等待队列取的 prefill 块大小。这个等式是硬约束：批的总 token 数受限于 kernel 模板的 tile 容量、TMEM/SMEM 占用与分页 KV 的块表长度，超了就要拆批，拆批就多一次 kernel 启动。因此 <em>B</em><sub>iter</sub> 不是可调参数，而是给定 kernel 与显存布局下的常量，真正的自由度是在两项之间挪动配额。</p>\n<p>配额分配的伪代码落到可实现层面，核心是三个量：decode 队列的 SLO 余量、chunk 的剩余进度、以及上一轮的实测 <em>T</em><sub>iter</sub>。思路如下（伪代码以文字描述结构，不落 <pre>）：调度器每轮先算 decode 侧的最小必需配额——把在跑序列按 TPOT 目标反推本轮必须发出的 token 数，取其中位或高分位作为 <em>B</em><sub>decode</sub><sup>min</sup>；再用 <em>B</em><sub>iter</sub> 减去它得到 <em>B</em><sub>chunk</sub><sup>max</sup>；然后按等待队列头部请求的剩余 prompt 长度与已等待时长做加权，取 <em>B</em><sub>chunk</sub> = min(512, 剩余长度, <em>B</em><sub>chunk</sub><sup>max</sup>)。512 是给定事实中的 chunk 粒度锚点，也是 kernel 启动开销与 prefill 项量级之间的经验折中。</p>\n<p>代价在这里显形：<em>B</em><sub>decode</sub><sup>min</sup> 抬得越高，decode 的 TPOT 越稳，但 <em>B</em><sub>chunk</sub> 被压缩，长 prompt 反复入队却推不动，出现饥饿；反之 chunk 配额放大，prefill 高峰时段 decode 序列的 TPOT 抖动超出 SLO。工程判断是给 decode 侧留一个硬下限（按 SLO 反推），把剩余预算全部给 chunk，而不是按请求数均分——按请求数均分会让短 decode 序列占着配额不产出，长 prompt 拿不到块。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-17\">十七 · 统一 kernel 模板下的掩码与查询形态</h3>\n<p>背驮能成立的前提是 chunk 与 decode 走同一 kernel 模板，而不是两套 kernel 交替启动。attention 侧对 chunk 用因果掩码：chunk 内第 <em>i</em> 个 token 只能看见本 chunk 之前的位置与 chunk 内前 <em>i</em>−1 个位置，掩码矩阵是下三角；对 decode 序列则是单 token 查询，query 长度为一，KV 侧读全部分页块。二者在同一个 tile 循环里被拼成 batch 维：chunk 贡献 <em>s</em><sub>chunk</sub> 行 query，decode 贡献 <em>s</em><sub>dec</sub> 行 query，KV 读取按各自的分页块表寻址。</p>\n<p>推导上要说明为什么这不增加渐近代价：chunk 的 attention 计算量正比于 <em>s</em><sub>chunk</sub> 与已累积 KV 长度的乘积，decode 的计算量正比于 <em>s</em><sub>dec</sub> 与各自 KV 长度的乘积，二者在 batch 维拼接后由同一 MMA 指令流处理，tile 划分按 query 行切分，因此总计算量就是两项之和，没有额外项。真正的额外代价在中间状态：chunk 未耗尽时，其已算出的 KV 必须写回分页块并在下一轮重新读入，这部分读写是纯带宽开销，落在 <em>T</em><sub>mem</sub> 里，也是 util 偏离 1 的主要来源之一。</p>\n<p>具体例子：一个 512 token 的 chunk 在因果掩码下，其第 512 行的 query 要读前面 511 个位置的 KV，而 decode 序列的单 token query 要读它自己的全部历史 KV。若某 decode 序列历史长度为数千 token，它的 KV 读取字节数远超 chunk 内任一行的读取量，于是这一轮 <em>C</em><sub>dec</sub>·<em>s</em><sub>dec</sub> 项主导，chunk 的计算被带宽节拍掩盖——这正是背驮想要的互补，但也意味着 chunk 的推进速度受制于 decode 序列的历史长度分布，长历史 decode 越多，chunk 越慢。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-18\">十八 · 中间状态保存与 chunk 重入队的代价模型</h3>\n<p>chunk 完成后若 prompt 未耗尽则重新入队，已耗尽则转入 decode 队列。重入队不是零成本：本轮算出的 KV 要落盘到分页块，下一轮作为历史 KV 被读回；同时该请求的调度元数据（已消费 token 数、块表指针、掩码偏移）要在队列间迁移。代价可写成每 chunk 的固定开销 <em>c</em><sub>k</sub>（kernel 启动 + 元数据迁移）加上与 chunk 大小成正比的 KV 写读开销。当 chunk 取 512 时，<em>c</em><sub>k</sub> 被摊薄到 512 个 token 上；若因 decode 挤压把 chunk 降到几十 token，<em>c</em><sub>k</sub> 占比骤升，调度器本身成为瓶颈——这是给定事实中明确的失败模式。</p>\n<p>推导的关键一步是把重入队次数与 prompt 长度挂钩：长度 <em>L</em> 的 prompt 在 chunk 大小 <em>s</em><sub>chunk</sub> 下需要 ⌈<em>L</em>/<em>s</em><sub>chunk</sub>⌉ 轮，总固定开销正比于该轮数。因此 chunk 不能无限小，其下界由 <em>c</em><sub>k</sub> 与单 token 有效计算时间之比决定：当 <em>c</em><sub>k</sub> 接近一个 chunk 的计算时间时，再切小就纯亏。工程上把 chunk 下限钉在能让 prefill 项与 decode 项同量级的位置，512 是给定事实给出的锚点，实际部署应按 kernel 启动实测延迟反推，而非照抄。</p>\n<p>具体例子：一个长 prompt 被切成 512 token 块，若其总长为数千 token，则需数轮到十余轮重入队；每轮都要把该 chunk 的 KV 写入分页块并在下一轮读回。若这些轮次恰好落在 decode 高峰，chunk 配额被压到很小，轮数成倍增加，固定开销线性上升，长 prompt 的 TTFT 被拉长而非缩短——背驮的收益被重入队成本吃掉，这是调度器必须监测的负反馈回路。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-19\">十九 · 稳定性技巧与失败模式的判别信号</h3>\n<p>用 token 预算隔离 decode 与 prefill 的资源占用，是防止长 prompt 饿死短请求的核心手段。判别信号有三个，都可从每轮采样得到：其一，decode 序列的 TPOT 高分位相对其 SLO 的超出量，若在 prefill 高峰时段持续超出，说明 <em>B</em><sub>decode</sub><sup>min</sup> 设低了；其二，等待队列头部请求的已等待轮数，若某长 prompt 连续多轮只拿到远小于 512 的 chunk，说明 chunk 配额被 decode 挤占，饥饿正在发生；其三，util 的轮间方差，若方差大而均值低，说明调度器在两种配额间来回震荡，而非稳定贴近 max 下界。</p>\n<p>稳定化的做法是把配额调整做成低通滤波而非每轮重算：<em>B</em><sub>chunk</sub> 的目标值按 decode SLO 余量与 chunk 进度加权，但实际下发值对上轮值做滑动平均，避免一轮给满一轮给零的抖动。代价是响应变慢：当负载突变（一批短 rollout 同时到达）时，滤波后的配额需要数轮才收敛，这段时间内 util 偏低。工程判断是滤波窗口取数轮量级，与 chunk 重入队的轮数量级对齐，使配额变化与 chunk 生命周期同步，而不是与单轮节拍同步。</p>\n<p>另一个稳定性要点是 chunk 进度参与配额：等待队列按“剩余长度 / 已等待时长”排序，进度落后的长 prompt 在配额分配时获得加权，从而在 decode 高峰也能拿到最小可用 chunk，避免无限饥饿。这与按请求数均分的朴素做法相反——后者会让长 prompt 永远排在短请求之后。代价是短请求的 TTFT 在长 prompt 加权时略升，需要在 SLO 里同时约束两者，给定事实中的负载配方正是这样做的。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-20\">二十 · 与相邻算法的公式级差别</h3>\n<p>分页 KV 批量 Rollout 解决的是显存分配粒度，其公式落在块表与碎片率上；预填解码分离 Rollout 把两阶段拆到不同 GPU 池，其公式落在跨池传输带宽与池间负载均衡上。本算法的公式 <em>T</em><sub>iter</sub> ≈ max(计算项, 带宽项) 之所以成立，恰恰因为不拆池：同一批 SM 上计算与带宽是两条独立路径，拆池后两条路径分处不同硬件，max 退化为两池各自的节拍之和加传输项，互补性消失。这是公式层面的分界，不是部署偏好。</p>\n<p>适用边界的公式表达是：当 <em>C</em><sub>pre</sub>·<em>s</em><sub>chunk</sub>/FLOPS 与 <em>C</em><sub>dec</sub>·<em>s</em><sub>dec</sub>/BW 量级可比时收益最大；当 decode 序列历史极长使带宽项远超计算项，或 prompt 极短使计算项可忽略时，背驮退化为纯 decode 或纯 prefill，收益归零。规模上限受 <em>B</em><sub>iter</sub> 与 kernel 启动开销约束：批越大，单轮固定开销摊得越薄，但 tile 容量与分页块表长度封顶；chunk 越小，重入队轮数越多，固定开销占比越高。工程上应把这两个约束画成二维可行域，在域内取使 util 最大的 (<em>s</em><sub>chunk</sub>, <em>B</em><sub>decode</sub>) 组合，而不是把 512 当常数。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-21\">二十一 · 背驮调度的失效边界：预算挤占、块粒度与饥饿回路</h3>\n<p>核心公式的推导关键一步在“取最大而非求和”：预填块的计算占用与解码序列的带宽占用在同一迭代内并行，因此迭代时间由较慢的一侧决定，而不是两者相加。$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right)$$ 利用率 $\\text{util}=(T_{\\text{compute}}+T_{\\text{mem}})/T_{\\text{iter}}$ 只有在两侧恰好等长时才接近 1；一旦 $B_{\\text{chunk}}$ 远大于 $B_{\\text{decode}}$，解码侧被完全遮蔽，util 退化为纯预填的利用率，背驮的收益归零。工程上应把 $B_{\\text{iter}}=B_{\\text{decode}}+B_{\\text{chunk}}$ 当作硬约束，让 $B_{\\text{chunk}}$ 随解码队列的 token 配额反向伸缩，而不是固定 512。</p>\n<p>失效条件有三类，且互相耦合。其一是块粒度过小：chunk 切分引入额外的 kernel 启动与中间状态保存，调度开销占比随块数线性上升，调度器本身成为瓶颈，此时增大 chunk 反而更快。其二是解码 TPOT 抖动：解码序列被 chunk 挤占 token 预算，在预填高峰时段 TPOT 超出 SLO，短请求的尾延迟虽被压低，但稳态解码的抖动被放大。其三是饥饿回路：长 prompt 反复入队却因解码优先而拿不到 chunk 配额，进度停滞，TTFT 无界增长。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>工程对策</th></tr></thead><tbody><tr><td>块过小、调度开销上升</td><td>每轮调度耗时占迭代比例升高</td><td>设 chunk 下限，按 kernel 启动开销标定</td></tr><tr><td>解码 TPOT 抖动超 SLO</td><td>高峰时段 TPOT p99 抬升</td><td>为 $B_{\\text{decode}}$ 设保底配额</td></tr><tr><td>长 prompt 饥饿</td><td>chunk 进度长期停滞</td><td>按进度提升 chunk 配额权重</td></tr></tbody></table>\n<p>伪代码落到可实现层面，调度循环每轮做三件事：先按解码 SLO 算出保底 $B_{\\text{decode}}$，剩余预算给 chunk；取块后与全部解码序列拼批，attention 对 chunk 走因果掩码、对解码走单 token 查询，共用同一 kernel 模板；块完成后按是否耗尽分流回队列。规模上限由此确定：受单批 token 预算与 kernel 启动开销共同约束，超过该点后增大 chunk 不再提升 util，只会拉长解码侧的等待。</p>\n<h3 id=\"alg-chunked-prefill-decode-sec-22\">二十二 · 请求形态：混合长度样本池是唯一能吃到红利的负载</h3>\n<p>背驮解码的收益来源不是算法本身，而是批次内两类工作负载的瓶颈互补：prefill 块吃 FLOPS，decode 序列吃显存带宽。这决定了它对请求形态有硬性偏好——只有当同一批次里同时存在“计算饥饿”的长 prompt 与“带宽饥饿”的活跃 decode 序列时，<span class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right)$$</span> 中的两项才会接近，util 才可能逼近 1。若样本池长度分布单峰且窄——比如全部是 200 token 的短指令，或全部是 8K 以上的长文档——批次内就只剩一种瓶颈，背驮退化为普通连续批处理，还额外背上了 chunk 切分的开销。</p>\n<p>RL rollout 的样本池天然是长短混合的：同一策略在不同环境里采出的轨迹，prompt 长度从几十 token 的格式校验到数万 token 的上下文拼接不等。这正是该机制的目标负载。工程判断上，先量一下样本池的长度分布：若 p50 与 p99 的比值小于一个量级，收益有限；若跨两个量级以上，且长 prompt 占比足以让等待队列非空，才值得启用。等待队列为空时，调度器每轮取不到 chunk，<span class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span> 退化为纯 decode 预算，机制空转。</p>\n<p>代价侧要盯住一个具体指标：decode 序列被 chunk 挤占 token 预算后，TPOT 在 prefill 高峰时段抖动。长短混合越极端，抖动越大——因为长 prompt 的 chunk 配额需求越迫切，调度器越倾向于从 <span class=\"formula\">$$B_{\\text{decode}}$$</span> 里切肉。所以“混合”是收益的前提，也是抖动的来源，两者同源。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-23\">二十三 · 长度分布：chunk 尺寸必须与 prompt 长度分位数对齐</h3>\n<p>chunk 尺寸 512 token 不是普适常数，它应当由长度分布的低分位决定。设 prompt 长度分布为 <span class=\"formula\">$$L\\sim P$$</span>，若大量 prompt 长度落在 512 以下，则这些请求在单个 chunk 内就走完 prefill，直接转入 decode 队列——它们从不参与“背驮”，只是快速穿过等待队列，机制对它们没有增益，反而多了一次入队/出队的状态保存。真正被背驮的是长度远超 chunk 的长 prompt，它们要经历 <span class=\"formula\">$$\\lceil L/512\\rceil$$</span> 轮切分，每轮都要保存中间状态（已计算的 KV、注意力掩码偏移、进度游标）。</p>\n<p>于是长度分布决定了两件事：一是中间状态保存的总量，长 prompt 的 chunk 数越多，跨轮保存的 KV 页与游标越多，显存与调度元数据的开销线性上升；二是长 prompt 的完成时延，它被拉长为 chunk 数乘以每轮间隔。若 p99 长度是 p50 的数十倍，p99 请求的 chunk 数也数十倍于中位请求，它在等待队列里的驻留时间被 decode 的 SLO 反复挤压，形成饥饿。</p>\n<p>具体例子：一个样本池 p50 为 300 token、p99 为 12K token。中位请求一个 chunk 内完成，不占背驮通道；p99 请求需要约 24 个 chunk，若每轮 decode 预算优先，它可能要在队列里等十几轮才凑齐配额。此时 TTFT 的 SLO 若按 p99 设定，就会与 decode 的 TPOT SLO 直接冲突——调度器必须在两者间做显式取舍，而不是让 chunk 配额被动地由 decode 剩余预算决定。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-24\">二十四 · 并发与批大小：按 token 预算计批，而非按请求数</h3>\n<p>这是负载配方里最容易被工程团队搞错的一条。传统连续批处理按“最大并发请求数”配置批大小，背驮解码必须改成按 token 预算：<span class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span> 的每一项都是 token 数，不是序列数。原因很直接：一个 decode 序列每轮只贡献 1 个 token，一个 chunk 贡献 512 个 token，两者对 SM 与带宽的占用差两个量级。若按请求数配批，调度器会把几十个 decode 序列和一个 chunk 拼在一起，看似“满载”，实际 token 预算被 chunk 单方面吃掉，decode 的 TPOT 直接崩。</p>\n<p>正确的并发配方是：先由 decode 序列的 SLO 反推 <span class=\"formula\">$$B_{\\text{decode}}$$</span> 的下限——保证在跑序列每轮都能拿到自己的 1 个 token 且 TPOT 不超阈值；再把剩余预算给 <span class=\"formula\">$$B_{\\text{chunk}}$$</span>。并发上限因此不是“能塞多少请求”，而是“token 预算除以平均每请求每轮 token 数”。decode 并发高时，<span class=\"formula\">$$B_{\\text{decode}}$$</span> 被摊薄到每个序列，chunk 配额被压缩，长 prompt 进度变慢；decode 并发低时，chunk 配额充裕，长 prompt 快速推进。这个反比关系是负载配方的核心张力。</p>\n<p>系统代价体现在调度器本身：按 token 预算计批意味着每轮都要重算配额分配，调度逻辑从“取请求”变成“解一个带 SLO 约束的预算分配问题”。chunk 过小时，这个分配问题的求解频率上升，kernel 启动次数上升，调度器 CPU 侧开销占比上升，最终调度器成为瓶颈——这是失败模式之一，不是理论担忧。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-25\">二十五 · SLO 配方：TTFT 与 TPOT 必须同时进入调度决策</h3>\n<p>背驮解码的 SLO 是双约束：decode 的 TPOT 与长 prompt 的 TTFT。单约束调度（只看 TPOT）会让 chunk 配额被无限压缩，长 prompt 饥饿；单约束调度（只看 TTFT）会让 chunk 配额膨胀，decode 抖动。可用事实里明确写了“按 decode 序列的 SLO 与 chunk 进度动态调整每轮 chunk token 配额”，这句话的工程含义是：调度器每轮要同时读取两个信号——在跑 decode 序列的当前 TPOT 余量，以及等待队列头部长 prompt 的已完成 chunk 比例。</p>\n<p>一个可落地的伪代码思路：每轮先算 decode 侧的安全预算 <span class=\"formula\">$$B_{\\text{decode}}^{\\text{safe}}$$</span>，即在当前 TPOT 余量下 decode 序列还能承受的 token 数；剩余预算全给 chunk，但设一个下限 <span class=\"formula\">$$B_{\\text{chunk}}^{\\text{min}}$$</span>，防止长 prompt 被饿死。当等待队列头部请求的 chunk 进度落后于其 TTFT 截止时间对应的进度曲线时，抬高 <span class=\"formula\">$$B_{\\text{chunk}}^{\\text{min}}$$</span>，代价是 decode 侧 TPOT 抖动增大。这是一个显式的取舍旋钮，而不是隐式的副作用。</p>\n<p>具体代价：TTFT 与 TPOT 的 SLO 越紧，两者的可行域越可能不相交。当样本池 p99 长度极大而 decode 并发又高时，双 SLO 同时满足的预算分配可能不存在，调度器只能违约一侧。此时工程判断是：优先保 decode 的 TPOT（因为它影响所有在跑请求），让长 prompt 的 TTFT 违约并记录，而不是让抖动扩散到整个批次。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-26\">二十六 · 负载不对时的三种崩法</h3>\n<p>第一种：chunk 过小。切分引入额外 kernel 启动与中间状态保存，chunk 小到一定程度，每轮的有效计算占比被启动开销吃掉，<span class=\"formula\">$$\\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</span> 里的分母被固定开销撑大，util 不升反降。这不是“稍微慢一点”，而是机制从增益翻转为净损失。判据是：单 chunk 的计算时间与 kernel 启动加状态保存时间可比时，就该放大 chunk 或关闭背驮。</p>\n<p>第二种：decode 被挤占。prefill 高峰时段，chunk 配额持续挤压 <span class=\"formula\">$$B_{\\text{decode}}$$</span>，decode 序列的 TPOT 抖动超出 SLO。这在 decode 并发高、长 prompt 集中到达时最典型——两者同时争抢同一批 token 预算，而预算总量受单批 token 上限约束。表现是 p99 TPOT 出现规律性尖峰，与 chunk 调度轮次同频。</p>\n<p>第三种：长 prompt 饥饿。长 prompt 反复入队，但每轮 chunk 配额都被 decode 挤占，进度停滞。它占着等待队列头部，却拿不到预算，TTFT 无限拉长。这种崩法最隐蔽，因为 GPU 利用率看起来很高——批次里全是 decode，util 数字漂亮，但长 prompt 的 SLO 已经烂掉。三种崩法共同指向一个判断：负载配方不对时，背驮解码的 util 指标会骗人，必须同时看 TTFT 与 TPOT 的分位曲线才能识别。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-27\">二十七 · 配方核对清单与规模上限</h3>\n<p>上线前按四项核对：长度分布是否跨量级、等待队列是否常态非空、decode 并发是否留出 chunk 预算空间、chunk 尺寸是否与长度低分位对齐。四项里任何一项不满足，机制要么空转要么净损失。规模上限受单批 token 预算与 kernel 启动开销约束——批次 token 总量有上限，chunk 与 decode 共享这个上限，因此并发规模不能靠无限加请求数来扩，只能靠提高单批 token 效率来扩。</p>\n<p>部署配方上，单节点多卡张量并行、KV 沿用分页块管理、prefill 中间状态需在 chunk 间保存，这三条共同决定了状态保存的显存成本随 chunk 数线性增长。工程上应把 chunk 进度游标与已算 KV 页作为一等调度元数据管理，而不是当作临时变量——因为饥饿判定与配额调整都依赖它。最终判断落在一条：背驮解码不是“开了就快”的开关，它是一个对负载形状敏感的调度契约，配方对了才兑现，配方错了先伤尾延迟再伤吞吐。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-28\">二十八 · 负载配方与失效边界：什么时候该背驮，什么时候不该</h3>\n\n<p>背驮解码不是普适调度器，它的收益完全由请求形态决定。适合它的负载有明确画像：样本池长度分布呈双峰或多峰——大量短 prompt 的 decode 序列已经在跑，同时不断有长 prompt 涌入等待队列；prefill 与 decode 部署在同一批 GPU 上，没有拆池；SLO 同时约束 decode 的 TPOT 与长 prompt 的 TTFT，且两者量级可比。此时每轮迭代的 token 预算按 <span class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$</span> 切分，调度器按 token 而非按请求数组批，从等待队列取一个 512 token 的 chunk 与全部在跑 decode 序列拼成一个 batch，attention 对 chunk 走因果掩码、对 decode 走单 token 查询，共用同一 kernel 模板。判断收益是否成立，看迭代时间是否被两侧瓶颈中较大者支配：<span class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</span>。只有当 prefill 的计算占用与 decode 的带宽占用在时间上大致重叠、util 接近 1 时，背驮才真正把气泡填掉；若两侧严重失衡，max 退化为单侧瓶颈，拼批只是把空闲从一侧搬到另一侧。</p>\n\n<p>负载不对时的第一类失效是 decode 侧被挤占。chunk 与 decode 共享同一个 token 预算，长 prompt 高峰时段调度器若按 chunk 进度优先分配，decode 序列每轮拿到的 token 配额被压缩，TPOT 出现周期性抖动并越过 SLO。这在 RL rollout 中尤其危险：短 rollout 的尾延迟本已因长 prompt 独占 SM 被拉长，背驮若不能保证 decode 的配额下限，只是把长尾从“停摆气泡”换成“持续抖动”，p99 未必改善。第二类是长 prompt 饥饿：chunk 反复入队但每轮配额被 decode 挤走，prompt 永远走不到耗尽点，TTFT 无界增长。抑制手段是让 chunk 进度参与配额决策——已推进比例越高，下一轮获得的 chunk token 越多，形成对长请求的渐进式补偿，而不是固定 512 一刀切。</p>\n\n<p>第三类失效来自切分本身的开销。chunk 切分引入额外的 kernel 启动与 prefill 中间状态保存，chunk 越小，单位 token 承担的启动与状态读写成本越高，调度器自身成为瓶颈。规模上限因此受两个量约束：单批 token 预算（决定 chunk 能切多细而不挤占 decode）与 kernel 启动开销（决定 chunk 不能切多细）。工程判断可以落在一张简单的配方表上：</p>\n\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>背驮是否合适</th><th>主要代价</th></tr></thead><tbody><tr><td>长短混合、decode 常驻、同池部署</td><td>合适，util 提升明显</td><td>chunk 状态保存、TPOT 轻微抖动</td></tr><tr><td>长度高度均匀、几乎无等待队列</td><td>不合适，无 chunk 可背</td><td>拼批开销纯属浪费</td></tr><tr><td>decode 序列极长、TPOT SLO 极紧</td><td>不合适，配额冲突不可调和</td><td>TPOT 抖动越界</td></tr><tr><td>长 prompt 占比极高、短请求稀少</td><td>不合适，应走分离式预填</td><td>长 prompt 饥饿、调度器瓶颈</td></tr></tbody></table>\n\n<p>与相邻方案的分工要讲清楚：分页 KV 批量 Rollout 解决的是显存分配粒度，预填解码分离 Rollout 把两阶段拆到不同 GPU 池、以池间传输换隔离，而背驮坚持不拆池、在同一批次内互补计算与带宽瓶颈。这意味着它的适用边界被“同池”锁死——一旦 decode 的 TPOT SLO 紧到无法容忍任何 chunk 挤占，或长 prompt 的 TTFT SLO 紧到必须独占 SM 冲刺，正确做法是切到分离式预填，而不是继续调 chunk 大小。反过来，若负载以短 prompt 为主、等待队列长期为空，背驮的拼批逻辑没有可背之驮，调度开销纯属净损失，应退回普通连续批处理。量化档位在此不改变结论，但会移动平衡点：低精度下 prefill 的 FLOPS 项与 decode 的 BW 项比例变化，直接决定 max 由哪一侧支配，配方需按实际精度档重算 chunk 与 decode 的配额比。</p>\n<h3 id=\"alg-chunked-prefill-decode-sec-29\">二十九 · 硬件档位：先定 SM 预算，再定卡数</h3>\n<p>背驮解码的部署起点不是“买几台机器”，而是先回答一个问题：每轮迭代里，decode 的带宽需求与 prefill 的算力需求能否被同一组 SM 同时喂饱。Blackwell 的 tcgen05 与 TMEM 让单 SM 的 MMA 吞吐抬升，但 prefill 的瓶颈仍是 FLOPS，decode 的瓶颈仍是 HBM 带宽与 KV 读取。硬件档位的第一条判断是：单卡能否容纳目标模型的权重加一份可接受的 KV 池。权重放不下就谈不上同池部署，只能退回分离式预填/解码那条路。第二条判断是 SM 的“可切分性”：背驮解码要求同一批次内既有 chunk 的因果掩码注意力，又有 decode 的单 token 查询，两者走同一 kernel 模板，因此 SM 上必须留出足够的寄存器与 TMEM 给两条路径的中间状态，而不是把 SM 压到只剩一条路径的极限占用。</p>\n<p>档位划分按单节点内 NVLink 域的大小来做。GB200/GB300 NVL72 把 72 个 GPU 放在一个 NVLink 5 域里，张量并行可以跨 8 卡甚至更大，代价是每轮迭代的 all-reduce/all-gather 延迟进入关键路径；B200/B300 八卡节点则是更常见的起步档位。判断标准是：把 $$T_{\\text{iter}}$$ 拆成计算项与集合通信项，若通信项在 prefill 高峰时段超过计算项的固定比例，说明 TP 度数过高，chunk 的算力被通信吃掉，应降 TP 或改用 EP+TP 混合。工程上先按“权重能放下、KV 池有余量、TP 通信不主导”三条筛出候选档位，再用下面的迭代时间公式做粗算校验：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>这个式子的用法是反推：给定 s_chunk=512 与在跑 decode 序列数，算出两项各自的时间，取大者作为一轮的下界；若 util 明显低于 1，说明两项没有真正重叠，问题往往出在 kernel 模板不统一或 SM 被单一路径独占，而不是卡不够。具体例子：一个八卡 B200 节点跑中等规模模型，TP=8 时 all-reduce 每层两次，chunk 计算项与通信项在同一量级，此时把 TP 降到 4、把剩余卡留给独立副本做数据并行，反而能让背驮批次的 util 更接近 1。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-30\">三十 · 并行拓扑：同池内的 TP/EP 与副本切分</h3>\n<p>背驮解码的前提是 prefill 与 decode 同池，因此拓扑设计的核心矛盾是：prefill 的 chunk 需要大 TP 来压低单块延迟，decode 的长序列需要 KV 分布在尽量少的卡上以减少读取跳数。两者折中的做法是把 TP 度数定在“chunk 计算项不被通信主导”的最小值，把剩余并行度用于副本级数据并行——每个副本独立维护自己的 decode 队列与 prefill 等待队列，副本之间不共享 KV，只共享入口路由。这与 KV 中心分离式池化是两条路：后者把 KV 抽成独立层，本方案把 KV 留在副本内，用分页块管理，避免跨副本 KV 拉取进入迭代关键路径。</p>\n<p>当模型宽度不足以支撑高 TP 时，用 EP 承担专家维度的切分，attention 部分仍走 TP。此时要注意 chunk 的因果掩码注意力在 EP 下需要 all-to-all 把 token 路由到专家所在卡，chunk 越小、路由次数越多，all-to-all 的启动开销占比越高。工程判断是：EP 组大小与 chunk 大小联动，chunk 取 512 token 时 EP 组不宜超过单节点 NVLink 域的一半，否则路由延迟会侵蚀 prefill 的计算窗口。decode 侧的单 token 查询在 EP 下同样要走路由，但 decode 序列多、每序列每轮只出一个 token，路由的批处理效率取决于调度器是否把同一专家的 token 聚在一起发。</p>\n<p>拓扑落地时还要给调度器留出“预算隔离”的物理基础：decode 队列与 prefill 等待队列若共享同一组 SM，则 token 预算 $$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$ 是唯一能防止长 prompt 饿死短请求的闸门。拓扑上表现为每个副本内固定一份 decode 常驻配额，chunk 只能用剩余配额；跨副本时，路由层按各副本的 chunk 进度做加权分发，把长 prompt 优先送到 chunk 配额空闲的副本，抑制单副本内的饥饿。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-31\">三十一 · 量化方案：精度档位与 chunk 中间状态的显存账</h3>\n<p>量化档位的选择在背驮解码里有一个额外约束：chunk 的中间状态要在 chunk 之间保存，量化越激进，中间状态的还原与累加越容易引入数值漂移，而 decode 侧对数值漂移的容忍度低于 prefill。可行的事实是部署配方未给出具体量化档位，因此配方思路是分路径定档：权重与 KV 走低精度档位以压带宽，prefill chunk 的激活与累加保持较高精度档位，decode 的单 token 查询复用同一套 KV 低精度读取但在 attention 输出处做一次精度对齐。NVFP4/FP8 的具体稳定化手段属于另一条目的主题，这里只强调它在部署配方中的位置：量化档位不是全局一个数，而是按“权重 / KV / prefill 激活 / decode 激活”四张表分别定，且四张表要能在同一 kernel 模板里共存。</p>\n<p>显存账要算三块：权重、KV 池、chunk 中间状态。前两块决定单卡能否装下模型与并发序列，第三块决定 chunk 之间能否无缝续跑。chunk 中间状态包括已算部分的 KV、注意力累加器与位置编码偏移，按 512 token 一块计，块数等于 prompt 长度除以 512；长 prompt 的中间状态在等待队列里排队时持续占显存，若 KV 池按分页块管理，这些中间状态必须计入分页账本，否则会出现“chunk 排队把 KV 池吃满、decode 新序列无法分配”的失败模式。工程做法是给 prefill 等待队列设一个中间状态显存上限，超限时暂停取新 chunk，让在跑的 chunk 先耗尽转入 decode 队列。</p>\n<p>带宽侧的代价体现在 decode 的 TPOT 上：KV 低精度读取降低了每 token 的读取字节数，但 chunk 的激活高精度写入抬高了每轮迭代的写带宽。若一轮里 chunk 的写带宽与 decode 的读带宽叠加超过 HBM 上限，迭代时间由带宽项主导，util 反而下降。判断方法是把一轮的读写字节数按 $$B_{\\text{decode}}$$ 与 $$B_{\\text{chunk}}$$ 分摊，看带宽项是否超过计算项；超过就调小 chunk 配额或把 chunk 的激活档位降一档，用精度换带宽。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-32\">三十二 · KV 策略：分页块、中间状态与驱逐顺序</h3>\n<p>KV 沿用分页块管理是给定事实，配方要定的是块大小、预留比例与驱逐顺序。块大小与 chunk 大小不必相等：chunk 是调度单位（512 token），块是分配单位，块小于 chunk 可以让长 prompt 的中间状态按需增长，避免一次性预留整段 prompt 的 KV。预留比例按 decode 常驻序列的峰值并发定，给 prefill 中间状态留出的份额要显式设上限，否则长 prompt 排队会把 decode 的分配空间挤掉。驱逐顺序上，decode 运行队列里的序列优先级高于 prefill 等待队列的中间状态：前者被驱逐会直接拉高 TPOT 并触发重算，后者被驱逐只需重跑未完成的 chunk，代价是浪费已算的算力但不影响在线请求的 SLO。</p>\n<p>中间状态的保存粒度决定了 chunk 过小时的失败模式。chunk 取 512 token 时，每块的中间状态是一次 kernel 启动的产物；chunk 再小，kernel 启动与状态保存的开销占比上升，调度器本身成为瓶颈。配方上把 chunk 大小与块大小解耦后，可以用“块内多 chunk”的方式摊薄启动开销：一个分页块容纳多个 chunk 的中间状态，chunk 之间只做指针切换不做重新分配。代价是块内碎片增加，KV 池的有效容量下降，需要在预留比例里补偿。</p>\n<p>KV 策略还要与并行拓扑对齐：TP 下 KV 按头切分到各卡，分页块的账本要在 TP 组内一致，否则 chunk 续跑时各卡对“已算到哪一块”的判断会分叉。EP 下 KV 按专家所在卡分布，decode 的单 token 查询需要把 KV 读取与专家路由合并成一次访问，避免两次跨卡往返。具体例子：TP=4、块大小覆盖两个 512 token chunk 时，chunk 续跑的指针切换在组内广播一次即可，若块大小与 chunk 不对齐，每次续跑都要重算块内偏移，调度开销随 chunk 数线性上升。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-33\">三十三 · 调度参数：token 预算、chunk 配额与 SLO 反馈环</h3>\n<p>调度参数的可复现配置思路是三层反馈环。第一层是每轮 token 预算 $$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$，其中 $$B_{\\text{decode}}$$ 按在跑 decode 序列数与每序列每轮一个 token 计，$$B_{\\text{chunk}}$$ 是留给 prefill 的配额；两者按 SLO 动态分配，decode 的 TPOT 逼近上限时压缩 $$B_{\\text{chunk}}$$，长 prompt 的 TTFT 逼近上限时扩大 $$B_{\\text{chunk}}$$。第二层是 chunk 大小，取 512 token 为基准，按 kernel 启动开销占比上下调；chunk 过小时调度器成为瓶颈，这一点在失败模式里已明确。第三层是 chunk 进度，用于抑制长 prompt 饥饿：等待队列按“已算 chunk 数 / 总 chunk 数”排序，进度落后且等待时间长的 prompt 获得配额加权。</p>\n<p>伪代码思路如下：每轮先取 decode 运行队列的全部序列，算出 $$B_{\\text{decode}}$$；再按 SLO 余量算 $$B_{\\text{chunk}}$$；从等待队列按进度加权取一个 chunk，若 chunk 未耗尽则带中间状态重新入队，耗尽则转入 decode 队列；最后按本轮实际耗时更新 SLO 余量，供下一轮分配。这个环的关键是“按 token 预算而非请求数组批”，请求数不进入预算公式，避免长 prompt 因单请求 token 多而被误判为大请求。</p>\n<p>参数整定的代价体现在两个抖动源：decode 序列被 chunk 挤占 token 预算时，TPOT 在 prefill 高峰时段抖动；chunk 配额被 decode 挤占时，长 prompt 反复入队却拿不到配额，出现饥饿。配方上给两个抖动源各设一条硬边界：TPOT 抖动的容忍带按 SLO 的固定比例设，超出即冻结 $$B_{\\text{chunk}}$$ 一轮；饥饿的判据是长 prompt 的等待轮数超过阈值，触发配额加权提升。这两条边界不需要调参实验，只需要在调度器里作为不变量存在。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-34\">三十四 · 可复现配置的落地顺序</h3>\n<p>把上述五块拼成一个可复现的配置，落地顺序是：先定硬件档位与 TP 度数，用迭代时间公式校验 util 是否接近 1；再定副本切分与 EP 组大小，确保 chunk 的 all-to-all 不进入关键路径；然后定四张量化表与 KV 块大小，把 chunk 中间状态计入分页账本并设上限；最后整定三层调度环，把 TPOT 容忍带与饥饿阈值写成不变量。每一步的验收标准是一个可观测的量：util、TPOT 的 p99、长 prompt 的 TTFT、KV 池的有效容量。四个量里任何一个偏离，回退到上一步改参数，而不是继续往下堆。</p>\n<p>一个具体的配置思路示例：单节点八卡 B200，TP=4 两个副本，每副本独立维护 decode 队列与 prefill 等待队列；KV 走分页块，块大小覆盖两个 512 token chunk，中间状态显存上限设为 KV 池的固定份额；量化按权重/KV 低精度、prefill 激活较高精度、decode 激活对齐四张表；调度器每轮按 $$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$ 分配，chunk 取 512 token，进度加权抑制饥饿。验收时看两个数：prefill 高峰时段的 TPOT p99 是否在容忍带内，长 prompt 的等待轮数是否低于阈值。若 TPOT 抖动超标，先冻结 chunk 配额一轮再观察；若饥饿出现，先提升进度加权再观察。这套顺序不依赖具体模型的实验数字，只依赖给定事实里的机制与约束，因此可以在不同模型规模上重复。</p>\n<p>最后一个工程判断落在 kernel 模板的统一性上：背驮解码的收益来自同一批次内两条路径互补瓶颈，若 chunk 的因果掩码注意力与 decode 的单 token 查询走了两套 kernel，SM 上的中间状态无法复用，util 公式里的重叠项就退化为串行相加。配置落地时把“同一 kernel 模板”作为硬约束写进验收清单，比调任何调度参数都更能决定这套配方是否成立。</p>\n<h3 id=\"alg-chunked-prefill-decode-sec-35\">三十五 · 迭代时间的双瓶颈分解与利用率上限</h3>\n<p>背驮解码的每一轮迭代，本质是在同一个 kernel 模板里同时喂两类形状不同的工作：chunk 的因果掩码 prefill 与 decode 的单 token 查询。把一轮的墙钟时间拆成两股流，得到本部分反复使用的判据：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>这个 max 结构决定了系统的第一处崩点不在算力也不在带宽，而在<strong>两者配比失衡时的空转</strong>。当 $s_{\\text{chunk}}$ 偏大，compute 项主导，decode 的带宽窗口被压缩，$T_{\\text{mem}}$ 无法被完全重叠，util 掉；当 $s_{\\text{chunk}}$ 偏小，mem 项主导，prefill 的算力占不满，SM 上出现碎片化空槽，util 同样掉。真正的最优点是让两项在数值上接近相等，即 $s_{\\text{chunk}}/s_{\\text{dec}} \\approx (\\text{BW}/\\text{FLOPS})\\cdot(C_{\\text{dec}}/C_{\\text{pre}})$。工程上这意味着一件事：chunk 大小不是固定常量，而是随 decode 队列深度变化的<strong>反馈量</strong>。以 512 token 为初值可以，但一旦 decode 队列从 8 条涨到 64 条，$C_{\\text{dec}}\\cdot s_{\\text{dec}}$ 的带宽项会成比例放大，此时若仍按 512 切 chunk，compute 项被淹没，util 立刻滑落。调度器必须把 $B_{\\text{chunk}}$ 当作被控变量而非配置项。</p>\n<p>代价落到具体指标上：util 每掉 10 个百分点，等价于在同样功耗下损失约一成的 token 吞吐；而在功耗受限的 NVL72 机柜里，util 下滑并不会让功耗同比下降，因为 SM 空转期间时钟与电压并不会线性回落，于是每 token 的能耗反而上升。这是背驮解码在规模上去以后第一个暴露的隐性成本：<strong>能效比吞吐更早恶化</strong>。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-36\">三十六 · 显存：中间状态保存与分页块的双重压力</h3>\n<p>chunk 切分把一次 prefill 拆成多轮，直接后果是 prefill 的中间状态必须在 chunk 之间存活。对因果注意力而言，已处理 chunk 的 K/V 必须落进分页块池，下一 chunk 才能以因果掩码正确拼接。这意味着显存占用从“一次性峰值”变成“持续驻留”：一条长 prompt 在未耗尽前，其已算出的 KV 始终占据块池，且这部分块在 chunk 期间不能被 decode 的块复用策略回收。</p>\n<p>把账算清楚：设块池总容量为 $M_{\\text{kv}}$，decode 序列集合占用 $M_{\\text{dec}}$，正在背驮的 prefill 序列集合占用 $M_{\\text{pre}}$，则可用余量为 $M_{\\text{kv}} - M_{\\text{dec}} - M_{\\text{pre}}$。背驮解码的调度约束是每轮从等待队列取 chunk，但取之前必须先确认块池能容纳该 chunk 新增的 KV 页。若 $M_{\\text{pre}}$ 因多条长 prompt 同时在途而膨胀，调度器会被迫缩小 $B_{\\text{chunk}}$ 甚至暂停取 chunk，此时 decode 独占批次，prefill 队列积压——系统退化为纯 decode，长 prompt 的 TTFT 迅速劣化。这就是规模上去后显存先于算力崩的路径：不是显存不够放模型权重，而是<strong>块池被在途 prefill 的中间状态挤占，导致调度自由度消失</strong>。</p>\n<p>具体例子：混合样本池中若同时有 32 条长度远超 chunk 的长 prompt 在途，每条在途 prompt 驻留的 KV 页数随 chunk 进度线性增长，块池余量被持续侵蚀；此时即便 decode 队列只有少量短序列，调度器也无法把 $B_{\\text{chunk}}$ 维持在 512，只能降到更小块，而更小块又触发下一节的启动开销问题。显存压力与调度粒度在这里形成负反馈。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-37\">三十七 · 带宽：decode 的命脉被 chunk 的读写挤兑</h3>\n<p>decode 阶段每 token 的代价几乎全在权重与 KV 的读取带宽上，$C_{\\text{dec}}\\cdot s_{\\text{dec}}/\\text{BW}$ 这一项就是它的下界。背驮解码的设计初衷正是用 prefill 的算力占用去填 decode 的带宽空闲，但反过来，prefill chunk 自身也要读写 KV 页与激活，会与 decode 争抢同一份 HBM 带宽。当 chunk 较大时，prefill 的 KV 写入量在单轮内抬升，decode 的有效带宽被压缩，$T_{\\text{mem}}$ 上升，TPOT 抖动。</p>\n<p>量化这个挤兑：单轮内 prefill 新增 KV 写入量正比于 $s_{\\text{chunk}}$ 与该层注意力头维度，decode 需要读取的 KV 量正比于在跑序列数与已生成长度。两者共享同一 HBM 通道，带宽分配不是调度器能直接控制的，只能通过 $B_{\\text{chunk}}$ 间接调节。因此在 prefill 高峰时段，decode 的 TPOT 会出现可观测的抖动——这正是本算法已知的失败模式之一，且抖动幅度随 $s_{\\text{chunk}}$ 增大而增大。工程判断是：把 $B_{\\text{chunk}}$ 的上限绑定到 decode 的 TPOT SLO 余量上，而不是绑定到算力利用率上；宁可让 compute 项略微欠载，也不让 mem 项突破 SLO。</p>\n<p>另一个带宽层面的代价是 chunk 的中间状态保存本身：chunk 结束时需把部分激活或注意力中间量写回，下一轮再读入，这部分往返流量在小 chunk 时占比显著上升。chunk 越小，单位有效 token 摊到的状态读写越多，带宽效率越差，与调度开销上升叠加，构成小 chunk 的双重惩罚。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-38\">三十八 · 通信：张量并行下 chunk 的集合通信放大</h3>\n<p>部署配方是单节点多卡张量并行。张量并行把每层的注意力和 MLP 切到多卡，每层前后各有一次 all-reduce 或 reduce-scatter/all-gather。背驮解码把一轮拆成 chunk 与 decode 两股工作拼在同一批次，但集合通信的<strong>次数</strong>由层数决定，与批次内 token 数无关；也就是说，chunk 切得越细，同样的层数被触发更多轮，每轮都带着完整的集合通信开销，而每轮承载的有效 token 却更少。</p>\n<p>通信代价可以写成：单轮通信时间约正比于层数乘以单次集合通信延迟，而单轮有效 token 产出为 $B_{\\text{decode}} + B_{\\text{chunk}}$。于是通信效率（每单位通信开销换来的 token）随 $B_{\\text{chunk}}$ 减小而下降。在 NVLink 5 的高带宽下，单次集合通信的延迟仍不可忽略，尤其是小消息的 all-reduce 受延迟而非带宽支配。当 chunk 降到很小（例如远低于 512），通信从“被计算掩盖”变成“暴露在关键路径上”，$T_{\\text{iter}}$ 的 max 结构里多出一项无法重叠的通信项，util 公式中的分母被抬高而分子不变，利用率直接塌陷。</p>\n<p>具体例子：张量并行度为 8 时，一层两次集合通信，若模型层数较多，一轮迭代内的集合通信次数是固定的；把 chunk 从 512 降到 128，轮数变为四倍，集合通信总次数变为四倍，而每轮 token 产出并未同比增加，通信开销在总时间中的占比显著上升。这就是规模上去后通信先于算力成为瓶颈的机制：不是带宽不够，而是<strong>轮数乘以固定延迟</strong>。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-39\">三十九 · 功耗与尾延迟：SLO 约束下的真实上限</h3>\n<p>背驮解码提升了平均 util，但尾延迟的行为更复杂。p99 由两类事件主导：一是长 prompt 的 chunk 配额被 decode 挤占导致的饥饿，二是 prefill 高峰时段 decode 的 TPOT 抖动。前者使长 prompt 的 TTFT 尾部拉长，后者使短 rollout 的 TPOT 尾部拉长。两者在 token 预算 $B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$ 的分配上是直接对立的：给 decode 多分，prefill 饥饿；给 chunk 多分，TPOT 抖动。规模上去后，队列深度增加，这个对立面的方差被放大，p99 比 p50 恶化得更快。</p>\n<p>功耗维度上，util 的提升并不等价于能耗的同比下降。prefill 是计算密集的，decode 是带宽密集的，两者拼在同一批次时，SM 的占用率上升但 HBM 的占用率也上升，整卡功耗向峰值靠拢。在 NVL72 机柜的功率封顶下，功耗上升会触发降频，而降频对 compute 项的影响大于对 mem 项的影响，于是 $T_{\\text{iter}}$ 的 max 结构发生偏移，原本平衡的配比被打破，util 再次下滑。这是一个闭环：背驮提升 util → 功耗上升 → 降频 → 配比失衡 → util 下降。规模越大，这个闭环越容易触发，因此容量规划必须把<strong>功率封顶下的可持续 util</strong>作为约束，而不是把峰值 util 当作目标。</p>\n<p>尾延迟的具体代价：若 decode 的 TPOT SLO 设为某个上界，prefill 高峰时段的抖动一旦突破它，短 rollout 的完成时间尾部被拉长，RL 训练侧的样本回流节奏被打乱。工程上应把 chunk 配额做成随 decode 队列 SLO 余量收缩的闭环控制，而不是固定 512。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-40\">四十 · 规模上去以后哪里先崩：一条判定顺序</h3>\n<p>把上述四类代价按规模增长的敏感度排序，可以得到一条工程判定顺序。第一崩的是<strong>显存块池余量</strong>：在途 prefill 的中间状态随长 prompt 数量线性膨胀，块池余量最先被侵蚀，调度自由度先丧失。第二崩的是<strong>通信轮数</strong>：chunk 被迫变小后，集合通信次数乘以固定延迟，暴露在关键路径上。第三崩的是<strong>带宽挤兑</strong>：prefill 高峰时 decode 的 TPOT 抖动突破 SLO。第四才是<strong>算力配比</strong>：util 的失衡是前三者连锁反应的结果，而非独立原因。</p>\n<p>判定用的伪代码思路：每轮调度前先算块池余量，若不足以容纳目标 chunk 则降 $B_{\\text{chunk}}$；再算通信暴露项，若轮数超过阈值则抬 $B_{\\text{chunk}}$ 以减少轮数；两者冲突时以块池余量为硬约束、以 TPOT SLO 为软约束，取满足硬约束下的最大 chunk。这个顺序把“规模上限受单批 token 预算与 kernel 启动开销约束”这句话落成了可执行的控制律：单批 token 预算决定 $B_{\\text{iter}}$ 的上界，kernel 启动与通信延迟决定 $B_{\\text{chunk}}$ 的下界，块池余量决定可行区间是否为空。当可行区间为空时，系统已到达该部署形态的规模上限，此时唯一出路是拆池——但那属于分离式预填/解码的范畴，不在本算法的能力边界内。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-41\">四十一 · 规模上去以后，先崩的是 token 预算而不是算力</h3>\n<p>这套方案的上限不在单卡 FLOPS，而在每轮迭代的 token 预算分配。核心约束是$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$$，两个配额互相挤占：chunk 拿多了，在跑 decode 序列的 TPOT 就在 prefill 高峰抖动；decode 拿多了，长 prompt 反复入队却拿不到配额，出现饥饿。迭代时间由两阶段中较长者决定，$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right)$$，而真正决定收益的是利用率 $\\text{util} = (T_{\\text{compute}}+T_{\\text{mem}})/T_{\\text{iter}}$。当 $B_{\\text{chunk}}$ 小到让 prefill 项远低于带宽项时，计算与访存的重叠窗口被浪费，util 反而下降——这是“切得越细越平滑”的直觉失效之处。</p>\n<p>第二个先崩的是调度器本身。chunk 切分引入额外 kernel 启动与中间状态保存，prefill 中间状态必须在 chunk 之间驻留显存，随并发 chunk 数线性增长；512 token 的块在单节点多卡张量并行下尚可摊薄启动开销，但若为压尾延迟把块降到很小，每轮固定开销占比上升，调度器从“编排者”变成瓶颈，GPU 等调度而非调度等 GPU。此时增加卡数只放大通信面：张量并行的 all-reduce 与 chunk 边界同步叠加，NVLink 带宽被调度粒度切碎，尾延迟 p99 不降反升。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触及的边界</th><th>系统代价</th></tr></thead><tbody><tr><td>并发 decode 序列数</td><td>token 预算被 decode 吃满</td><td>chunk 配额趋零，长 prompt 饥饿，TTFT 尾部拉长</td></tr><tr><td>chunk 尺寸调小</td><td>kernel 启动与状态保存开销</td><td>调度器成瓶颈，util 下降，功耗不降</td></tr><tr><td>张量并行度提高</td><td>chunk 边界通信同步</td><td>带宽切碎，TPOT 抖动超出 SLO</td></tr></tbody></table>\n<p>因此适用边界很明确：混合长度样本池、prefill/decode 同池部署时收益最大；一旦 decode 队列长期饱和或 SLO 对 TPOT 抖动极敏感，就该转向预填解码分离，把两阶段拆到不同 GPU 池，而不是继续在同一批次里挤压预算。工程判断的落点是：先按 decode SLO 反推 $B_{\\text{decode}}$ 的下限，剩余预算才归 chunk，并把 chunk 尺寸钉在启动开销可摊薄的下界之上——规模扩展时优先扩池而非扩批。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-42\">四十二 · 单批 token 预算封顶：规模上去先崩在调度器与 TPOT 抖动</h3>\n<p>背驮方案的天花板不在算力，而在每轮迭代的 token 预算 $B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$ 被双向挤压。规模上升时，decode 运行队列变长，$B_{\\text{decode}}$ 按 SLO 优先占满预算，留给 chunk 的配额被压到很小；若强行维持 512 token 的 chunk，单批序列数与 KV 分页块需求同时上涨，注意力 kernel 的 tile 划分与中间状态保存（chunk 间需保留因果掩码下的部分 K/V 与归一化统计）占用额外显存带宽。此时迭代时间由下式主导：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>当 $s_{\\text{chunk}}$ 缩小以腾预算，$T_{\\text{compute}}$ 项下降但 kernel 启动与状态保存的固定开销不随 chunk 线性缩小，util 反而掉；当 $s_{\\text{chunk}}$ 放大，$T_{\\text{compute}}$ 项压过带宽项，decode 的单 token 查询被迫等待同一 kernel 模板完成长 chunk 的因果掩码计算，TPOT 抖动直接越过 SLO。这就是规模上去后第一个崩点：不是显存先爆，而是 decode 的尾延迟先失控。</p>\n<p>第二个崩点在通信与功耗的耦合。单节点多卡张量并行下，chunk 的中间状态在 chunk 边界需跨卡同步，chunk 越小同步次数越多，NVLink 上的小消息占比上升，all-reduce 的有效带宽被启动延迟吃掉；同时 prefill 高峰时段 SM 同时跑计算密集的 chunk 与带宽密集的 decode，功耗曲线抬升，若机柜功耗封顶则触发降频，$T_{\\text{iter}}$ 被硬性拉长，util 公式中的分子不变而分母变大。工程判断是：把 chunk 配额与 decode 的 TPOT 预算做成闭环反馈，按 chunk 进度而非固定 512 调整每轮配额，并在调度器侧对长 prompt 设最小配额下限防止饥饿；一旦 kernel 启动开销占比超过单轮预算的可观比例，就应放弃同池背驮，转向预填解码分离的池化部署。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的系统量</th><th>触发条件</th></tr></thead><tbody><tr><td>decode 队列变长</td><td>TPOT 尾延迟</td><td>chunk 挤占 $B_{\\text{decode}}$</td></tr><tr><td>chunk 变小</td><td>调度器与 kernel 启动开销</td><td>固定开销占比上升</td></tr><tr><td>多卡张量并行</td><td>NVLink 小消息带宽</td><td>chunk 边界同步频繁</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-decode-sec-43\">四十三 · 精度漂移：chunk 边界上的数值不连续</h3>\n<p>背驮解码把一条长 prompt 拆成若干 512 token 的块，每块独立走一遍 attention 与 MLP，块间只保留 KV 与少量中间状态。问题就出在“只保留少量中间状态”上：如果某层在 chunk 末尾做了归约（layernorm 的均值方差、softmax 的行最大值、MoE 的 router logits），这些量在跨块拼接时必须与 decode 分支共享同一份统计口径，否则同一序列在不同 chunk 里会得到轻微不同的数值路径。工程上表现为：单条请求自身输出正常，但同一 prompt 在不同 chunk 配额下重跑，logprob 出现系统性偏移，RL 训练侧拿到的 ratio 与 rollout 侧对不上，梯度被污染。</p>\n<p>诊断手段是“重放对齐”：固定同一 prompt，分别用 chunk=512 与 chunk=整段两种配置各跑一次，逐 token 比对 top-1 logprob 差值分布。若差值集中在 chunk 交界处而非均匀分布，说明中间状态保存不完整；若差值随 chunk 数线性增长，说明累加器精度不足（FP32 累加被降级）。代价体现在显存与带宽：为消除漂移，需在 chunk 间保存每层的归约统计量，按层数 × 隐藏维度 × 2 个标量估算，单序列额外占用与层数成正比的常驻缓冲，在 decode 队列很长时这部分缓冲会与分页 KV 争抢显存。</p>\n<div class=\"formula\">$$\\Delta_{\\text{logprob}} = \\left| \\log p_{\\text{chunk}}(y_t) - \\log p_{\\text{full}}(y_t) \\right|,\\quad \\text{交界处}\\ \\Delta \\gg \\text{块内}\\ \\Delta$$</div>\n<p>具体例子：某 rollout 服务把 chunk 从 512 调到 256 以缓解尾延迟，结果 RL 侧 importance ratio 的方差明显变大，排查发现是 softmax 的行最大值在更短的块里被更频繁地重算，跨块拼接时未做全局 max 校正。回滚策略不是退回整段 prefill，而是把 chunk 固定回 512 并对归约量做全局校正，同时把该配置写入灰度白名单，只有经过重放对齐校验的 chunk 尺寸才允许上线。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-44\">四十四 · OOM：中间状态与分页 KV 的叠加峰值</h3>\n<p>背驮解码的显存峰值不在稳态，而在“一个 chunk 刚进入 attention、decode 序列的 KV 已满、下一块中间状态已预分配”的三重叠加时刻。分页 KV 的块管理本身是按需增长的，但 chunk 的中间状态（QKV 投影缓冲、attention 工作区、跨块保存的归约量）往往是按最大 chunk 尺寸静态预留的，两者叠加时峰值远超稳态占用。更隐蔽的是，调度器按 token 预算批处理，一个 batch 里 decode 序列数与 chunk 数同时达到上限，激活值总量按 batch 维度放大。</p>\n<p>监控要盯的不是平均显存，而是每轮迭代的瞬时峰值与分页池的碎片率。做法是在调度器里维护一个“预算-显存”联立检查：在拼批之前，用当前 decode 序列的 KV 块数加上待取 chunk 的中间状态估算值，与显存水位比较，超阈值就缩减本轮 chunk 配额而不是等 OOM 触发。代价是吞吐：缩减 chunk 配额会拉长长 prompt 的 TTFT，但比一次 OOM 导致整批回滚便宜得多。</p>\n<table class=\"mini\"><thead><tr><th>峰值来源</th><th>触发条件</th><th>工程对策</th></tr></thead><tbody><tr><td>chunk 中间状态静态预留</td><td>chunk 尺寸按最大值分配</td><td>按本轮实际 chunk token 动态分配</td></tr><tr><td>分页 KV 碎片</td><td>长短序列混合、块回收不及时</td><td>块回收与 chunk 入队同轮执行</td></tr><tr><td>batch 维度激活放大</td><td>decode 序列数与 chunk 同时打满</td><td>token 预算联立显存水位检查</td></tr></tbody></table>\n<p>具体例子：一个 NVL72 单节点多卡张量并行部署，decode 队列积压到接近分页池上限时，调度器仍按满额 512 token 取 chunk，结果在 chunk 的 attention 工作区分配时触发 OOM，整批 decode 一起失败。修复是把 chunk 配额改为“剩余显存可容纳的 token 数”反推，并在 chunk 入队前先回收已完成序列的 KV 块，峰值被压到稳态附近。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-45\">四十五 · 批抖动：TPOT 在 prefill 高峰的锯齿</h3>\n<p>decode 序列被 chunk 挤占 token 预算，直接后果是 TPOT 抖动。抖动不是随机噪声，而是与 chunk 入队节奏同频的锯齿：每轮取一个 chunk，该轮 decode 分到的 token 配额被压缩，TPOT 抬升；chunk 耗尽转入 decode 队列后，配额恢复，TPOT 回落。若 chunk 尺寸与 decode 序列的 SLO 不匹配，锯齿幅度会超出 SLO 容忍带，表现为 p99 TPOT 尖刺。</p>\n<p>量化抖动要用迭代级指标而非请求级均值：记录每轮 <span>B_decode</span> 与 <span>B_chunk</span> 的实际分配、该轮 decode token 的完成时间，算出 TPOT 的滚动标准差。诊断判据是：若 TPOT 尖刺与 chunk 入队轮次严格对齐，则是配额分配问题；若尖刺与 chunk 尺寸无关而与 batch 内序列数相关，则是 kernel 模板在混合 batch 上的效率问题。前者的代价是吞吐换稳定，后者要改 kernel 而非改调度。</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>具体例子：某服务把 decode 的 TPOT SLO 设为固定上限，prefill 高峰时 p99 连续越界。排查发现调度器按固定比例分配预算，未考虑 decode 序列的实时进度。改为按 decode 序列已等待时长加权分配 <span>B_decode</span>，并对 chunk 配额设上限，锯齿幅度收敛到 SLO 带内，代价是长 prompt 的 TTFT 略微拉长。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-46\">四十六 · 路由不均与长 prompt 饥饿</h3>\n<p>在多卡张量并行下，chunk 与 decode 拼成的 batch 要分发到各卡，若按请求数组而非 token 预算切分，会出现某些卡分到的 chunk token 多、某些卡几乎全是 decode，导致卡间负载不均，最慢的卡决定迭代时间。更严重的是长 prompt 饥饿：长 prompt 反复入队，但每轮 chunk 配额被 decode 挤占，chunk 进度停滞，TTFT 无界增长。这不是吞吐问题，是公平性问题。</p>\n<p>监控要同时看两个量：每卡的实际 token 处理量与 chunk 队列中每个请求的累计进度。判据是 chunk 队列里存在进度长时间不前进的请求，且其等待时长超过 decode 序列的 TPOT 抖动幅度。对策是在调度器里引入“chunk 进度老化”：按请求已等待轮次提升其 chunk 配额优先级，并对单轮 chunk 配额设下限，保证每个在队长 prompt 每若干轮至少前进一个块。代价是 decode 的 TPOT 在老化触发时被短暂压缩，需要与 SLO 容忍带对齐。</p>\n<ul><li>机制：token 预算切分替代请求数组切分，保证卡间按 token 均衡。</li><li>公式思路：伪代码为 <span>quota = base + α·age</span>，age 为请求等待轮次，α 由 SLO 余量反推。</li><li>代价：老化提升 chunk 配额时 decode TPOT 短暂抬升，需限制单轮抬升幅度。</li><li>例子：长 prompt 池中某条超长样本连续多轮未前进，老化触发后其 chunk 配额翻倍，两轮内完成 prefill，decode 侧仅出现一次可接受的小尖刺。</li></ul>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-47\">四十七 · 尾延迟尖刺的定位与回滚</h3>\n<p>尾延迟尖刺的来源有三类，必须分开定位，否则回滚会打错靶。第一类是 chunk 过小：kernel 启动与中间状态保存开销占比上升，调度器自身成为瓶颈，表现为所有请求的迭代时间整体抬升而非个别尖刺。第二类是 chunk 过大：单轮 chunk 占用过多计算，decode 配额被压到极低，尖刺集中在 chunk 入队轮。第三类是混合 batch 上 kernel 模板退化：因果掩码的 chunk 与单 token 查询的 decode 走同一模板，但某些形状组合下模板效率下降，尖刺与 chunk 尺寸无单调关系。</p>\n<p>定位方法是把迭代时间按“纯 decode 轮”“含 chunk 轮”分组统计，再看尖刺是否落在组内。回滚要分级：配置级回滚（chunk 尺寸、预算分配比例）最快，代码级回滚（kernel 模板、中间状态保存逻辑）最慢但最彻底。工程判断是：只要尖刺与 chunk 尺寸单调相关，就先做配置级回滚并保留灰度对照；只有当配置回滚无效且尖刺与形状组合相关时，才动 kernel。</p>\n<table class=\"mini\"><thead><tr><th>尖刺类型</th><th>判据</th><th>回滚动作</th></tr></thead><tbody><tr><td>chunk 过小</td><td>整体迭代时间抬升，与 chunk 尺寸反相关</td><td>调回 512 token 档位</td></tr><tr><td>chunk 过大</td><td>尖刺集中在含 chunk 轮</td><td>降 chunk 配额上限</td></tr><tr><td>kernel 退化</td><td>尖刺与尺寸无单调关系</td><td>回滚 kernel 模板版本</td></tr></tbody></table>\n<p>具体例子：一次灰度把 chunk 从 512 降到 128 想改善 TTFT，结果 p99 迭代时间整体变差，调度开销占比上升。按上表判据属于第一类，配置级回滚到 512 后指标恢复，灰度对照保留一周以确认无二次漂移。回滚本身也要监控：回滚后的第一轮要检查 chunk 队列积压是否被瞬间释放造成新的 decode 尖刺，必要时分批恢复而非一次性切回。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-48\">四十八 · 当互补失效：五类故障的判据、观测点与回退路径</h3>\n<p>背驮解码的收益来自一个脆弱的等式：每轮 token 预算被切成 <span class=\"inline-math\">B_decode + B_chunk</span>，两类工作在同一 kernel 模板里互补瓶颈。一旦互补关系被打破，故障不会以“变慢”这种温和形态出现，而是以五种可辨识的形态暴露。第一类是<b>精度漂移</b>：chunk 的因果掩码与 decode 的单 token 查询共用同一 kernel 模板，若 chunk 边界处的 KV 分页块未与 decode 序列的块表对齐，或 chunk 间中间状态（如 softmax 归一化因子、部分归约和）保存时被降精度截断，长 prompt 的注意力输出会出现系统性偏差——表现为长 prompt 的 rollout 奖励分布相对短 prompt 整体偏移，而非随机噪声。诊断手段是在 chunk 边界插入一致性校验：对同一 prompt 分别走“整段预填”与“512 token 分块预填”两条路径，比对首 token 的 logits 最大绝对差；阈值应按量化档位设定，一旦越界即判定中间状态保存路径有损。第二类是 <b>OOM</b>，其成因不是 KV 增长而是<b>中间状态驻留</b>：每个未耗尽的 chunk 都要在队列里保留部分归约结果，等待队列深度乘以每 chunk 状态大小构成一笔隐式显存开销，在长 prompt 密集到达时先于 KV 触顶。监控应把“prefill 等待队列的驻留状态字节数”作为独立指标，与分页 KV 池水位分开告警。</p>\n<p>第三类是<b>批抖动</b>，判据是迭代时间 <span class=\"inline-math\">T_iter</span> 的方差而非均值。由 <span class=\"inline-math\">T_iter ≈ max(C_pre·s_chunk/FLOPS, C_dec·s_dec/BW)</span> 可知，当 <span class=\"inline-math\">s_chunk</span> 取 512 而 decode 序列数骤降时，迭代从带宽受限翻转为计算受限，util 中的 <span class=\"inline-math\">T_compute</span> 占比跳变，调度器下一轮又按新 util 调低 chunk 配额，形成正反馈振荡。观测点是逐迭代的 <span class=\"inline-math\">T_compute/T_iter</span> 比值序列，健康状态下该比值应在窄带内波动；若出现周期性尖峰且与 chunk 配额调整同相，即判定为抖动而非负载变化。第四类是<b>路由不均</b>：单节点多卡张量并行下，chunk 的因果掩码使不同 TP rank 承担的注意力计算量随 chunk 位置变化，靠近 prompt 尾部的 chunk 在各 rank 上负载更均衡，而首块因掩码稀疏出现 rank 间空转，表现为 rank 级 SM 利用率的标准差随 chunk 序号单调变化。第五类是<b>尾延迟尖刺</b>，其机制是长 prompt 反复入队却每轮被 decode 的 SLO 挤占配额，chunk 进度停滞，TTFT 的 p99 出现阶梯式抬升——这正是“抑制饥饿”策略在 decode 压力下的反面。</p>\n<p>监控的最小集合应围绕调度器的三个内部量而非 GPU 通用指标：等待队列的 chunk 进度分布（识别饥饿）、每轮实际 <span class=\"inline-math\">B_chunk/B_iter</span> 比值（识别挤占）、以及 chunk 完成到重新入队的间隔（识别调度器自身成为瓶颈）。当 chunk 过小，kernel 启动与中间状态保存的开销占比上升，间隔指标会先于吞吐指标恶化，这是最早的回滚信号。回滚不应是全局关闭背驮，而应分级：一级回滚把 <span class=\"inline-math\">B_chunk</span> 下限抬高（例如从 512 提到更大块），以吞吐换调度开销；二级回滚在 decode TPOT 逼近 SLO 时冻结 chunk 配额，让 prefill 退回独占 SM 的长任务形态，接受气泡但保住 decode 的尾延迟；三级回滚才切回预填/解码分离的池化部署。分级的关键判据是：若尾延迟尖刺伴随 chunk 进度停滞，说明是饥饿而非抖动，应优先调高 chunk 配额而非降低；若尖刺伴随 util 振荡，则相反。这套判据把“回滚”从运维直觉变成由队列进度与 util 比值共同决定的确定性动作。</p>\n<table class=\"mini\"><thead><tr><th>故障形态</th><th>首要观测点</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度漂移</td><td>分块与整段预填的 logits 差</td><td>修正中间状态保存精度</td></tr><tr><td>OOM</td><td>等待队列驻留状态字节</td><td>限制队列深度</td></tr><tr><td>批抖动</td><td>T_compute/T_iter 序列方差</td><td>冻结配额调整</td></tr><tr><td>路由不均</td><td>rank 级 SM 利用率标准差</td><td>按 chunk 序号重排</td></tr><tr><td>尾延迟尖刺</td><td>chunk 进度停滞时长</td><td>抬高 B_chunk 下限</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-decode-sec-49\">四十九 · 对照轴：资源互补、池边界与显存粒度</h3>\n<p>把分块预填背驮解码放进同族算法谱系里，第一件要判定的不是“谁更快”，而是“瓶颈是否互补、池边界是否可拆、显存粒度是否已受控”。这三条轴决定了它是不是正确选择，而不是调参问题。分页KV批量Rollout动的是显存分配粒度——它让KV按块生长、按块回收，解决的是碎片与预留浪费；预填解码分离Rollout动的是拓扑——把prefill与decode拆到不同GPU池，用池间传输换池内纯净；KV中心分离式池化把KV本身做成可寻址资源，跨实例复用前缀。本算法不动池、不动分配器，只在同一批次内做时间维度的资源互补：让prefill的计算占用去填decode的带宽空闲。因此判定顺序应是：先问显存粒度是否已经稳定（否则chunk中间态与分页块叠加会把碎片问题放大），再问池是否值得拆（拆池要付跨池KV传输与调度两套队列的代价），最后才问同池背驮是否够用。</p>\n<p>互补性的量化判据直接来自迭代时间模型：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{C_{\\text{pre}}\\cdot s_{\\text{chunk}}}{\\text{FLOPS}},\\ \\frac{C_{\\text{dec}}\\cdot s_{\\text{dec}}}{\\text{BW}}\\right),\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>若两项量级接近，max 退化为一者主导，util 接近 1，背驮收益最大；若 prefill 项远大于 decode 项，chunk 会反过来压住 decode 的 token 预算，TPOT 抖动；若 decode 项远大于 prefill 项，chunk 填进去只是搭便车，收益有限但仍无害。工程上要的是“两项同量级”的负载配方，而不是无脑开 chunk。举例：一个长短混合样本池，decode 侧在跑数十条序列、每轮各取单 token，prefill 等待队列里躺着若干条长 prompt；取 512 token 的 chunk 与全部 decode 序列拼批，若该步的 compute 时间与 decode 的带宽时间落在同一档，则这一轮既没浪费 SM 也没浪费 HBM 带宽；反之若 chunk 取到数千 token，compute 项压倒 mem 项，decode 序列的 TPOT 就被拉长到 SLO 之外。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-50\">五十 · 决策表：五族算法的适用条件与代价位</h3>\n<p>下表只列判定条件与代价落点，不复述各算法机制（机制见各自条目）。选择时按行从上到下排除：先排除显存粒度未稳的场景，再排除必须拆池的场景，剩下的才轮到背驮。</p>\n<table class=\"mini\"><thead><tr><th>算法族</th><th>适用条件</th><th>主要代价位</th><th>与本算法的关系</th></tr></thead><tbody>\n<tr><td>分页KV批量Rollout</td><td>KV 长度方差大、批内序列频繁进出，显存碎片已成瓶颈</td><td>块表管理与分配器开销；块大小与命中率的折中</td><td>前置条件：粒度未稳时背驮的 chunk 中间态会加剧碎片</td></tr>\n<tr><td>预填解码分离Rollout</td><td>prefill 与 decode 的 SLO 量级差异大，或两阶段最优并行度不同</td><td>跨池 KV 传输带宽与延迟；两套调度队列；池间负载不均</td><td>替代方案：以拓扑换纯净，代价是传输</td></tr>\n<tr><td>KV中心分离式池化</td><td>多实例共享前缀、跨请求复用率高，需要把 KV 做成可寻址资源</td><td>池化层带宽与一致性维护；寻址延迟</td><td>正交：可与背驮叠加，但池化延迟会改变 chunk 配额节奏</td></tr>\n<tr><td>分块预填背驮解码（本算法）</td><td>混合长度样本池、prefill/decode 同池部署、两阶段瓶颈同量级</td><td>chunk 切分的 kernel 启动与中间态保存；decode 的 token 预算被挤占</td><td>自身：不拆池、不改分配器的时间维度互补</td></tr>\n<tr><td>特征级投机采样Rollout</td><td>decode 侧接受率可估、草稿成本低于收益</td><td>草稿模型显存与验证开销；接受率不达预期则净亏</td><td>正交：背驮稳定 TPOT 后，投机才有稳定的验证窗口</td></tr>\n</tbody></table>\n<p>读表要点：背驮与分离式是同一问题的两条解法，分界线是“跨池传输成本是否低于池内抖动成本”。若集群内 NVLink 域足够大、KV 传输能压在可接受延迟内，拆池更彻底；若传输要跨节点、KV 体量大，则同池背驮的零传输优势胜出。与分页KV的关系是先后而非并列：分页块管理把显存粒度做稳，背驮才有条件在 chunk 间保存中间态而不爆显存。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-51\">五十一 · 判定式：什么时候背驮会输给邻居</h3>\n<p>把选择写成可算的判据，比凭直觉拍板可靠。设拆池方案的单轮代价为跨池传输时间 $T_{\\text{xfer}}$ 与两池负载不均导致的空转 $T_{\\text{idle}}$ 之和；背驮方案的单轮代价为 chunk 调度开销 $T_{\\text{sch}}$ 与 decode 被挤占造成的 TPOT 越界惩罚 $T_{\\text{slip}}$ 之和。选择背驮的条件可写成：</p>\n<div class=\"formula\">$$T_{\\text{sch}}+T_{\\text{slip}} &lt; T_{\\text{xfer}}+T_{\\text{idle}}$$</div>\n<p>其中 $T_{\\text{sch}}$ 随 chunk 变小而上升（kernel 启动次数与中间态保存次数成正比），$T_{\\text{slip}}$ 随 chunk 变大而上升（decode 的 token 预算被挤压）。两者之和在某个 chunk 尺寸上取极小——这正是部署配方里“按 decode SLO 与 chunk 进度动态调整每轮 chunk token 配额”要寻找的工作点，512 token 只是给定事实中的一个锚点，不是普适最优。反过来，若 $T_{\\text{xfer}}$ 很小（同 NVLink 域、KV 体量可控），分离式几乎总赢，因为 $T_{\\text{idle}}$ 可通过两池独立扩缩容压掉；此时背驮的 $T_{\\text{slip}}$ 是结构性缺陷，无法靠调参消除。</p>\n<p>具体例子：一个 rollout 集群里 decode 侧 SLO 要求 TPOT 稳定在窄带内，而 prefill 侧长 prompt 的 TTFT 允许较宽；若两阶段并行度需求差异大（prefill 吃满 SM、decode 吃满带宽），拆池让各自按最优并行度跑，$T_{\\text{idle}}$ 用独立扩缩容吸收；若两阶段需求相近且 KV 传输要跨节点，则背驮的零传输更划算。判定的实操做法是先在单池上量出 $T_{\\text{sch}}$ 与 $T_{\\text{slip}}$ 随 chunk 尺寸的曲线，再估 $T_{\\text{xfer}}$，两者一比即可定案，不必先搭两套池做对照实验。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-52\">五十二 · 叠加与互斥：与正交算法的组合次序</h3>\n<p>背驮不是孤立开关，它与相邻算法有明确的叠加次序与互斥关系。可叠加的：分页KV批量Rollout（前置，粒度稳定）、KV中心分离式池化（正交，但池化寻址延迟会拉长 chunk 的取数路径，需把 chunk 配额调小以维持节奏）、特征级投机采样Rollout（后置，背驮把 TPOT 抖动压住后，投机验证窗口才稳定，否则草稿被频繁打断、接受率估计失真）。互斥或强竞争的：预填解码分离Rollout——两者解同一问题，同时开等于把 prefill 拆两处又背驮回 decode 批，调度器要维护三套队列，收益相互抵消；异步Rollout流水线在阶段划分上与背驮有重叠，若流水线已把 prefill 与 decode 错峰，背驮的互补空间被吃掉，需二选一。</p>\n<p>叠加次序的工程含义是资源账要按序算：先由分页块管理定下 KV 的显存上限，再由背驮定下每轮 token 预算 $B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}}$ 的切分，最后由投机定下 decode 侧的有效 token 产出率。三者任一环失配，整条链的吞吐就被最窄处卡住。举例：若池化层把前缀 KV 的取数延迟抬高，chunk 的中间态保存与取回变慢，$T_{\\text{sch}}$ 上升，此时应缩 chunk 而非加 chunk——这与“chunk 越大越省调度”的直觉相反，因为池化改变了代价结构。反之若投机接受率高、decode 侧每轮产出 token 变多，$B_{\\text{decode}}$ 的有效计算量上升，chunk 可适当放大以维持两项同量级。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-53\">五十三 · 规模上限与选型收口</h3>\n<p>背驮的规模上限由两个量夹住：单批 token 预算与 kernel 启动开销。批越大，chunk 与 decode 拼批的调度复杂度与中间态显存越高；chunk 越小，单位 token 摊到的 kernel 启动与状态保存开销越大，调度器本身成为瓶颈。给定事实把边界描述为“受单批 token 预算与 kernel 启动开销约束”，这意味着扩容不是线性外推：当 decode 序列数增长到使 $B_{\\text{decode}}$ 吃掉大部分预算时，chunk 配额被压到很小，$T_{\\text{sch}}$ 占比上升，此时应转向分离式或池化，而不是继续在同池里加序列。反过来，当样本池以短 prompt 为主、长 prompt 稀疏，背驮的收益本就有限，因为气泡出现的频率低，chunk 机制白付调度开销——这类负载直接用普通连续批处理即可。</p>\n<p>选型收口的工程判断可以压成三句话：显存粒度未稳，先上分页KV；两阶段 SLO 量级差异大且 KV 传输可承受，上分离式；两者都不成立、负载是长短混合且同池部署，才用背驮，并把 chunk 配额做成随 decode SLO 与 chunk 进度动态调整的闭环，而不是固定 512。最后一条最容易被忽略：固定 chunk 在负载漂移时会同时踩中 $T_{\\text{sch}}$ 与 $T_{\\text{slip}}$ 两个失败模式——prefill 高峰时 decode 被挤到 TPOT 越界，低谷时 chunk 过小使调度开销占比上升。把配额做成闭环，等于把选型判据从“选哪个算法”延伸到“选完之后如何随负载移动工作点”，这才是同族算法对照的落点。</p>\n\n<h3 id=\"alg-chunked-prefill-decode-sec-54\">五十四 · 同族算法怎么选：分块背驮的边界与失效条件</h3>\n<p>本方案与两个相邻算法常被混为一谈，但三者的资源边界完全不同。分页KV批量Rollout解决的是显存分配粒度问题——它让KV按页生长、按需回收，从而允许更多序列共存；它不改变prefill与decode在同一SM上的时间竞争。预填解码分离Rollout把两阶段拆到不同GPU池，用池间传输换取阶段隔离，代价是跨池KV搬运与池间负载不均衡。分块背驮则坚持同池部署，在同一批次内让prefill的计算密集与decode的带宽密集互补。因此选择的第一判据不是“哪个更快”，而是“池子能不能拆”：若集群有富余节点且跨池带宽充裕，分离方案能给出最干净的TPOT；若节点紧张、KV搬运成为新瓶颈，背驮是唯一不增加显存足迹的选项。第二判据是样本长度分布：混合长度样本池是背驮的主场，长度高度同质时chunk与decode的互补收益被摊薄，反而只剩切分开销。</p>\n<p>决策时把每轮token预算写成可分配的资源方程，比凭直觉选算法更可靠：</p>\n<div class=\"formula\">$$B_{\\text{iter}} = B_{\\text{decode}} + B_{\\text{chunk}},\\quad \\text{util} = \\frac{T_{\\text{compute}}+T_{\\text{mem}}}{T_{\\text{iter}}}$$</div>\n<p>其中$$B_{\\text{chunk}}$$取512 token量级时，chunk的因果掩码注意力与decode的单token查询能走同一kernel模板，计算与带宽在迭代内重叠；一旦$$B_{\\text{chunk}}$$被压到很小以给decode让路，kernel启动与chunk间中间状态保存的固定开销就开始吃掉重叠收益，调度器自身也可能成为瓶颈。反过来，若为压TPOT抖动而放大$$B_{\\text{decode}}$$，长prompt的chunk配额被持续挤占，等待队列反复入队却拿不到执行机会，出现长prompt饥饿——此时TTFT的p99恶化会抵消decode侧的一切改善。工程上应把$$B_{\\text{chunk}}$$设为不低于数百token的下限，并用chunk进度而非请求到达顺序做配额仲裁。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选分块背驮</th><th>选分离池</th><th>选分页KV批量</th></tr></thead><tbody><tr><td>节点余量</td><td>紧张，同池</td><td>充裕，可拆池</td><td>无关</td></tr><tr><td>长度分布</td><td>长短混合</td><td>长prompt占比高且稳定</td><td>序列数受显存限制</td></tr><tr><td>主约束</td><td>TPOT与TTFT同时受SLO约束</td><td>TPOT优先、可容忍搬运</td><td>显存碎片、并发上限</td></tr><tr><td>失效信号</td><td>chunk过小、调度开销占比升</td><td>跨池带宽饱和、池间不均衡</td><td>页表开销、分配抖动</td></tr></tbody></table>\n<p>失效条件的识别要落在可观测指标上，而不是等SLO报警。三个信号值得直接埋点：其一，单轮迭代中调度与kernel启动耗时占$$T_{\\text{iter}}$$的比例，该比例随$$B_{\\text{chunk}}$$缩小而单调上升，越过阈值即说明切分已不划算，应合并chunk或退回整块prefill；其二，prefill高峰时段decode的TPOT分布漂移，若漂移超出SLO而$$B_{\\text{decode}}$$已无法再让，说明同池互补的余量耗尽，该考虑分离池；其三，长prompt在等待队列中的驻留轮数，持续增长即饥饿前兆，需提高其chunk配额或对其单独限流。规模上限由单批token预算与kernel启动开销共同决定：批越大重叠越充分，但单批预算受KV分页块与中间状态显存约束，超过后每轮只能装下更少的chunk，互补窗口随之收窄。因此这套方案适合中等规模、长短混合、同池部署且SLO同时约束TPOT与TTFT的rollout服务；当长prompt成为主导负载且节点可拆时，应果断转向分离池，把同池互补留给decode侧的短请求。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 批量生成调度与前缀共享</td></tr><tr><td>解决什么</td><td>RL rollout中长prompt的prefill是计算密集的长任务，会独占SM造成decode批次停摆，形成气泡，…</td></tr><tr><td>一句话机制</td><td>把长prefill切成固定token块，与正在进行的decode请求拼成同一批次，用decode的显存带宽空闲填补pr…</td></tr><tr><td>代价与失效</td><td>chunk切分引入额外kernel启动与中间状态保存，chunk过小时调度开销占比上升；decode序列被chunk挤占token预算，d…</td></tr><tr><td>后继</td><td>异步Rollout流水线</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-chunked-prefill-decode · 共 8 个片段</p>\n";break;}}})();
